; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: m65 (MEGA65 (45GS02)), starts in turbo mode
; ============================================================

			org $2001

;## ntc_m65_stub ntc_m65_boot
; the PRG's start (the compiler puts it first, at $2001): a BASIC line
; "10 BANK 0 : SYS 8209" then a jump to the start code
			dw ntc_m65_bnext, 10
			db $FE, $02, "0:", $9E, "8209", 0		; BANK 0 : SYS 8209
ntc_m65_bnext:
			dw 0
			jmp ntc_m65_boot				; 8209 = $2011

;## ntc_m65_boot ntc_plat_data ntc_data ntc_plat_screen ntc_m65_fontdata ntc_plat_exit
; ------------------------------------------------------------
; the start: the machine taken over, the screen, then ntc_start (the thread)
; ------------------------------------------------------------
ntc_m65_boot:
			sei
			cld
			lda #$47					; the VIC-IV's registers (I/O "knock")
			sta $D02F
			lda #$53
			sta $D02F
			lda #0						; no MAP: the CPU sees bank 0 (and $D000 I/O)
			tax
			tay
			taz
			map
			eom
			lda #0
			tab							; base page 0
			sta $D030					; no C65 ROM banked in
			lda #$35					; RAM at $A000 and $E000, I/O at $D000
			sta $01
			ldx #<$07EF					; the real stack, 16 bits
			txs
			ldy #>$07EF
			tys
			cle
			lda #0						; CIA 1's ports in (the joysticks)
			sta $DC02
			sta $DC03
			ldx #0						; keys still in the queue (the RETURN of RUN ...) dropped
ntc_m65_b_kq:
			lda $D610
			beq ntc_m65_b_kq1
			sta $D610
			dex
			bne ntc_m65_b_kq
ntc_m65_b_kq1:
			lda #$7F					; the CIAs' interrupts off
			sta $DC0D
			sta $DD0D
			lda $DC0D
			lda $DD0D
			lda #0						; the VIC's off
			sta $D01A
			lda #$FF
			sta $D019
			lda #<ntc_m65_nmi			; vectors (RAM: no KERNAL mapped)
			sta $FFFA
			lda #>ntc_m65_nmi
			sta $FFFB
			lda #<ntc_m65_boot
			sta $FFFC
			lda #>ntc_m65_boot
			sta $FFFD
			lda #<ntc_m65_brk
			sta $FFFE
			lda #>ntc_m65_brk
			sta $FFFF
			; RESTORE: one NMI from CIA 2's timer A that is never acknowledged holds
			; the NMI line low, so no further NMI (RESTORE's included) gets in
			lda #0
			sta $DD0E
			lda #8
			sta $DD04
			lda #0
			sta $DD05
			lda #$81
			sta $DD0D
			lda #$19					; one shot, load, start
			sta $DD0E
			ldx #0
ntc_m65_nwt:
			dex
			bne ntc_m65_nwt
			lda #$40					; 40 MHz: FAST ($D031) and VFAST ($D054)
			tsb $D054
			lda #0
			sta ntc_m65_lfc
			sta ntc_ticks
			sta ntc_ticks+1
			sta $07F2					; not ended
			sta $D020					; black border
			sta $D021
			sta ntc_m65_brkpc
			sta ntc_m65_brkpc+1
			lda $D7FA
			sta ntc_m65_lfc
			; the font: font8x8 (characters 32-127) at $E000, the rest blank (the VIC
			; shows its character ROM for a font at $1000 / $1800 / $9000 / $9800)
			ldx #0
			txa
ntc_m65_fcl:
			sta $E000,x
			sta $E100,x
			sta $E200,x
			sta $E300,x
			sta $E400,x
			sta $E500,x
			sta $E600,x
			sta $E700,x
			inx
			bne ntc_m65_fcl
			ldx #0
ntc_m65_fcp:
			lda ntc_m65_fontdata,x
			sta $E100,x
			lda ntc_m65_fontdata+256,x
			sta $E200,x
			lda ntc_m65_fontdata+512,x
			sta $E300,x
			inx
			bne ntc_m65_fcp
			; NTC_M65LOG test builds: the log's length
			ifd NTC_M65LOG
			lda #0
			sta ntc_m65_logn
			sta ntc_m65_logn+1
			jsr ntc_m65_logend
			endif
			lda #2						; 80 columns
			jsr ntc_plat_mode
			jmp ntc_start

; NMI (from CIA 2, once): not acknowledged, so the line stays low
ntc_m65_nmi:
			rti

; BRK (an IRQ never comes: the I flag is set): stop with a message
ntc_m65_brk:
			sei
			tsx
			stx ntc_m65_brkpc
			tsy
			sty ntc_m65_brkpc+1
			ldx #<$07EF
			txs
			ldy #>$07EF
			tys
			ldx #0
ntc_m65_bkl:
			lda ntc_m65_bktx,x
			beq ntc_m65_bkd
			stx ntc_m65_bkx
			jsr ntc_plat_putc
			ldx ntc_m65_bkx
			inx
			bne ntc_m65_bkl
ntc_m65_bkd:
			jsr ntc_plat_newline
			jmp ntc_plat_exit_stop
ntc_m65_bktx:	db "BRK - the program stopped", 0

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window $4000-$7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: $C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			tsx
			stx ntc_ip
			tsy
			sty ntc_ip+1
			ldx ntc_csp
			txs
			ldy ntc_csp+1
			tys
			endm
NTC_TS		macro			; back to the thread (A and the flags are kept)
			ldx ntc_ip
			txs
			ldy ntc_ip+1
			tys
			endm
NTC_POP		macro			; the next thread word into the base page word \1
			pla
			sta \1
			pla
			sta \1+1
			endm

ntc_start:
			tsx				; the real stack (the library's jsr calls)
			stx ntc_csp
			tsy
			sty ntc_csp+1
			ldx #<(main_thread-1)
			txs
			ldy #>(main_thread-1)
			tys
			rts

