z_q0		equ $40			; 32 bit (far) pointers
z_q1		equ $44
ntc_next:	rts						; continues the thread
ntc_ivar:	dw 0					; input / val: dest var
ntc_numbuf:	ds 16					; printint / long print: digits

;## ntc_jmp
; ------------------------------------------------------------
; branch tails: ntc_go takes a label off the thread and carries on there
; (SP = label - 1); ntc_goxy with the label in Y:X; ntc_skip2 steps over
; a label (not taken)
; ------------------------------------------------------------
ntc_go:
			pla
			tax
			pla
			tay
ntc_goxy:
			txa
			bne ntc_go_nb
			dey
ntc_go_nb:
			dex
			txs
			tys
			rts
ntc_skip2:
			pla
			pla
			rts

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jmp ntc_plat_exit_stop		; a MEGA65 taken over has nowhere to go back to

;## kw_goto_iffalse ntc_jmp
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			pla
			pla
			rts
kw_gif_go:
			jmp ntc_go

;## kw_goto_ifzero ntc_jmp
;kw_goto_ifzero, <var>, <label>  - branch if var = 0
kw_goto_ifzero:
			NTC_POP z_p0
			ldy #0
			lda (z_p0),y
			iny
			ora (z_p0),y
			bne kw_giz_no
			jmp ntc_go
kw_giz_no:
			pla
			pla
			rts

;## ntc_for_jump ntc_jmp
; ------------------------------------------------------------
; tails for the FOR / NEXT keywords: z_a = the variable's value, z_b = the
; limit; the label is next on the thread. Signed.
; ------------------------------------------------------------
ntc_for_blt:					; take the label if limit < var
			lda z_b
			cmp z_a
			lda z_b+1
			sbc z_a+1
			bvc ntc_for_b1
			eor #$80
ntc_for_b1:
			bmi ntc_for_take
			jmp ntc_skip2
ntc_for_bgt:					; take if limit > var
			lda z_a
			cmp z_b
			lda z_a+1
			sbc z_b+1
			bvc ntc_for_b2
			eor #$80
ntc_for_b2:
			bmi ntc_for_take
			jmp ntc_skip2
ntc_for_bge:					; take if limit >= var
			lda z_b
			cmp z_a
			lda z_b+1
			sbc z_a+1
			bvc ntc_for_b3
			eor #$80
ntc_for_b3:
			bpl ntc_for_take
			jmp ntc_skip2
ntc_for_ble:					; take if limit <= var
			lda z_a
			cmp z_b
			lda z_a+1
			sbc z_b+1
			bvc ntc_for_b4
			eor #$80
ntc_for_b4:
			bpl ntc_for_take
			jmp ntc_skip2
ntc_for_take:
			jmp ntc_go

;## kw_forupv ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p0),y
			sta z_a
			lda (z_p1),y
			sta z_b
			iny
			lda (z_p0),y
			sta z_a+1
			lda (z_p1),y
			sta z_b+1
			jmp ntc_for_blt

;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			NTC_POP z_p0
			NTC_POP z_b
ntc_next1:
			ldy #0
			lda (z_p0),y
			clc
			adc #1
			sta (z_p0),y
			sta z_a
			iny
			lda (z_p0),y
			adc #0
			sta (z_p0),y
			sta z_a+1
			bvs kw_n1_end
			jmp ntc_for_bge
kw_n1_end:
			jmp ntc_skip2

;## kw_next1v ntc_for_jump kw_next1l
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p1),y
			sta z_b
			iny
			lda (z_p1),y
			sta z_b+1
			jmp ntc_next1

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pla
			tax
			pla
			sta z_t0
			NTC_POP z_p0
			txa
			ldy #0
			sta (z_p0),y
			iny
			lda z_t0
			sta (z_p0),y
			rts

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p0),y
			sta (z_p1),y
			iny
			lda (z_p0),y
			sta (z_p1),y
			rts

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			NTC_POP z_p0
			lda #0
			tay
			sta (z_p0),y
			iny
			sta (z_p0),y
			rts

;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			beq kw_ft_t
			ldx #0
			beq kw_ft_go
kw_ft_t:
			ldx #$FF
kw_ft_go:
			NTC_POP z_p0
			txa
			ldy #0
			sta (z_p0),y
			iny
			sta (z_p0),y
			rts

; ============================================================
; Arithmetic (16 bit, wrapping)
; ============================================================

;## kw_inc
kw_inc:
			NTC_POP z_p0
			ldy #0
			lda (z_p0),y
			clc
			adc #1
			sta (z_p0),y
			iny
			lda (z_p0),y
			adc #0
			sta (z_p0),y
			rts

;## kw_dec
kw_dec:
			NTC_POP z_p0
			ldy #0
			lda (z_p0),y
			sec
			sbc #1
			sta (z_p0),y
			iny
			lda (z_p0),y
			sbc #0
			sta (z_p0),y
			rts

;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			NTC_POP z_p0
			NTC_POP z_p1
			NTC_POP z_p2
			ldy #0
			lda (z_p0),y
			clc
			adc (z_p1),y
			tax
			iny
			lda (z_p0),y
			adc (z_p1),y
			sta (z_p2),y
			dey
			txa
			sta (z_p2),y
			rts

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			NTC_POP z_p0
			NTC_POP z_a
			NTC_POP z_p2
			ldy #0
			lda (z_p0),y
			clc
			adc z_a
			tax
			iny
			lda (z_p0),y
			adc z_a+1
			sta (z_p2),y
			dey
			txa
			sta (z_p2),y
			rts

;## kw_subvv
;kw_subvv, <var1>, <var2>, <destvar>  - var1 - var2
kw_subvv:
			NTC_POP z_p0
			NTC_POP z_p1
			NTC_POP z_p2
			ldy #0
			lda (z_p0),y
			sec
			sbc (z_p1),y
			tax
			iny
			lda (z_p0),y
			sbc (z_p1),y
			sta (z_p2),y
			dey
			txa
			sta (z_p2),y
			rts

;## kw_sublv
;kw_sublv, <literal>, <var>, <destvar>  - literal - var
kw_sublv:
			NTC_POP z_a
			NTC_POP z_p1
			NTC_POP z_p2
			ldy #0
			lda z_a
			sec
			sbc (z_p1),y
			tax
			iny
			lda z_a+1
			sbc (z_p1),y
			sta (z_p2),y
			dey
			txa
			sta (z_p2),y
			rts

;## kw_2x
kw_2x:
			NTC_POP z_p0
			NTC_POP z_p2
			ldy #0
			lda (z_p0),y
			asl
			tax
			iny
			lda (z_p0),y
			rol
			sta (z_p2),y
			dey
			txa
			sta (z_p2),y
			rts

;## kw_4x
kw_4x:
			NTC_POP z_p0
			NTC_POP z_p2
			ldy #0
			lda (z_p0),y
			sta z_a
			iny
			lda (z_p0),y
			asl z_a
			rol
			asl z_a
			rol
			sta (z_p2),y
			dey
			lda z_a
			sta (z_p2),y
			rts

;## ntc_mul16
; z_a * z_b -> z_a (low 16 bits) with the hardware multiplier ($D770: A, $D774: B,
; $D778: the product). Uses A only. JSR or JMP / back by hand
ntc_mul16:
			lda z_a
			sta $D770
			lda z_a+1
			sta $D771
			lda #0
			sta $D772
			sta $D773
			sta $D776
			sta $D777
			lda z_b
			sta $D774
			lda z_b+1
			sta $D775
			lda $D778
			sta z_a
			lda $D779
			sta z_a+1
			rts

;## kw_mulvv ntc_mul16
;kw_mulvv, <var1>, <var2>, <destvar>  - low 16 bits
kw_mulvv:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p0),y
			sta z_a
			lda (z_p1),y
			sta z_b
			iny
			lda (z_p0),y
			sta z_a+1
			lda (z_p1),y
			sta z_b+1
ntc_mul_st:
			NTC_POP z_p2
			lda z_a
			sta $D770
			lda z_a+1
			sta $D771
			lda #0
			sta $D772
			sta $D773
			sta $D776
			sta $D777
			lda z_b
			sta $D774
			lda z_b+1
			sta $D775
			ldy #0
			lda $D778
			sta (z_p2),y
			iny
			lda $D779
			sta (z_p2),y
			rts

;## kw_mulvl ntc_mul16 kw_mulvv
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			NTC_POP z_p0
			NTC_POP z_b
			ldy #0
			lda (z_p0),y
			sta z_a
			iny
			lda (z_p0),y
			sta z_a+1
			jmp ntc_mul_st

;## ntc_div
; z_a / z_b signed, truncating: z_a = quotient, z_b = remainder (the
; dividend's sign). Divide by zero: quotient 0, remainder = dividend.
; -32768 / -1: quotient -32768, remainder 0. JSR (the real stack). Uses z_c, z_t0, z_t1
ntc_div:
			lda z_b
			ora z_b+1
			bne ntc_div_nz
			lda z_a
			sta z_b
			lda z_a+1
			sta z_b+1
			lda #0
			sta z_a
			sta z_a+1
			rts
ntc_div_nz:
			lda z_a+1
			sta z_t0					; the dividend's sign
			eor z_b+1
			sta z_t1					; the quotient's
			bit z_a+1
			bpl ntc_div_ap
			sec
			lda #0
			sbc z_a
			sta z_a
			lda #0
			sbc z_a+1
			sta z_a+1
ntc_div_ap:
			bit z_b+1
			bpl ntc_div_bp
			sec
			lda #0
			sbc z_b
			sta z_b
			lda #0
			sbc z_b+1
			sta z_b+1
ntc_div_bp:
			jsr ntc_udiv16
			bit z_t1
			bpl ntc_div_qp
			sec
			lda #0
			sbc z_a
			sta z_a
			lda #0
			sbc z_a+1
			sta z_a+1
ntc_div_qp:
			lda z_c
			sta z_b
			lda z_c+1
			sta z_b+1
			bit z_t0
			bpl ntc_div_rp
			sec
			lda #0
			sbc z_b
			sta z_b
			lda #0
			sbc z_b+1
			sta z_b+1
ntc_div_rp:
			rts
; z_a / z_b unsigned: z_a = quotient, z_c = remainder. Uses A, X, Y
ntc_udiv16:
			lda #0
			sta z_c
			sta z_c+1
			ldx #16
ntc_ud_lp:
			asl z_a
			rol z_a+1
			rol z_c
			rol z_c+1
			lda z_c
			sec
			sbc z_b
			tay
			lda z_c+1
			sbc z_b+1
			bcc ntc_ud_no
			sta z_c+1
			sty z_c
			inc z_a
ntc_ud_no:
			dex
			bne ntc_ud_lp
			rts

;## ntc_divk ntc_div
; the division keywords' tail: z_a / z_b, then the quotient (z_t7 = 0) or the
; remainder (z_t7 = 1) into the var whose address is next on the thread
ntc_divk:
			NTC_RS
			jsr ntc_div
			NTC_TS
			NTC_POP z_p2
			ldy #0
			ldx z_t7
			bne ntc_divk_r
			lda z_a
			sta (z_p2),y
			iny
			lda z_a+1
			sta (z_p2),y
			rts
ntc_divk_r:
			lda z_b
			sta (z_p2),y
			iny
			lda z_b+1
			sta (z_p2),y
			rts
; the two operands: vv (two vars: z_p0, z_p1), vl, lv
ntc_divk_vv:
			ldy #0
			lda (z_p0),y
			sta z_a
			lda (z_p1),y
			sta z_b
			iny
			lda (z_p0),y
			sta z_a+1
			lda (z_p1),y
			sta z_b+1
			jmp ntc_divk

;## kw_divvv ntc_divk
;kw_divvv, <var1>, <var2>, <destvar>  - var1 \ var2
kw_divvv:
			NTC_POP z_p0
			NTC_POP z_p1
			lda #0
			sta z_t7
			jmp ntc_divk_vv

;## kw_divvl ntc_divk
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			NTC_POP z_p0
			NTC_POP z_b
			ldy #0
			lda (z_p0),y
			sta z_a
			iny
			lda (z_p0),y
			sta z_a+1
			lda #0
			sta z_t7
			jmp ntc_divk

;## kw_modvl ntc_divk
kw_modvl:
			NTC_POP z_p0
			NTC_POP z_b
			ldy #0
			lda (z_p0),y
			sta z_a
			iny
			lda (z_p0),y
			sta z_a+1
			lda #1
			sta z_t7
			jmp ntc_divk

;## kw_negv
kw_negv:
			NTC_POP z_p0
			NTC_POP z_p2
			ldy #0
			lda #0
			sec
			sbc (z_p0),y
			tax
			iny
			lda #0
			sbc (z_p0),y
			sta (z_p2),y
			dey
			txa
			sta (z_p2),y
			rts

;## kw_absv
kw_absv:
			NTC_POP z_p0
			NTC_POP z_p2
			ldy #1
			lda (z_p0),y
			bmi kw_abs_neg
			sta (z_p2),y
			dey
			lda (z_p0),y
			sta (z_p2),y
			rts
kw_abs_neg:
			ldy #0
			lda #0
			sec
			sbc (z_p0),y
			tax
			iny
			lda #0
			sbc (z_p0),y
			sta (z_p2),y
			dey
			txa
			sta (z_p2),y
			rts

;## kw_andvv
kw_andvv:
			NTC_POP z_p0
			NTC_POP z_p1
			NTC_POP z_p2
			ldy #0
			lda (z_p0),y
			and (z_p1),y
			sta (z_p2),y
			iny
			lda (z_p0),y
			and (z_p1),y
			sta (z_p2),y
			rts

;## kw_andvl
kw_andvl:
			NTC_POP z_p0
			NTC_POP z_a
			NTC_POP z_p2
			ldy #0
			lda (z_p0),y
			and z_a
			sta (z_p2),y
			iny
			lda (z_p0),y
			and z_a+1
			sta (z_p2),y
			rts

;## kw_orvv
kw_orvv:
			NTC_POP z_p0
			NTC_POP z_p1
			NTC_POP z_p2
			ldy #0
			lda (z_p0),y
			ora (z_p1),y
			sta (z_p2),y
			iny
			lda (z_p0),y
			ora (z_p1),y
			sta (z_p2),y
			rts

;## ntc_cmp
; tails: z_a = a, z_b = b, test a <rel> b
ntc_cmp_slt:
			lda z_a
			cmp z_b
			lda z_a+1
			sbc z_b+1
			bvc ntc_cmp_s1
			eor #$80
ntc_cmp_s1:
			bmi ntc_cmp_t
ntc_cmp_f:
			lda #1
			rts
ntc_cmp_t:
			lda #0
			rts
ntc_cmp_sge:
			lda z_a
			cmp z_b
			lda z_a+1
			sbc z_b+1
			bvc ntc_cmp_s2
			eor #$80
ntc_cmp_s2:
			bpl ntc_cmp_t
			lda #1
			rts
ntc_cmp_sgt:					; b < a
			lda z_b
			cmp z_a
			lda z_b+1
			sbc z_a+1
			bvc ntc_cmp_s3
			eor #$80
ntc_cmp_s3:
			bmi ntc_cmp_t
			lda #1
			rts
ntc_cmp_sle:					; b >= a
			lda z_b
			cmp z_a
			lda z_b+1
			sbc z_a+1
			bvc ntc_cmp_s4
			eor #$80
ntc_cmp_s4:
			bpl ntc_cmp_t
			lda #1
			rts
ntc_cmp_ult:
			lda z_a
			cmp z_b
			lda z_a+1
			sbc z_b+1
			bcc ntc_cmp_t
			lda #1
			rts
ntc_cmp_uge:
			lda z_a
			cmp z_b
			lda z_a+1
			sbc z_b+1
			bcs ntc_cmp_t
			lda #1
			rts
ntc_cmp_ugt:					; b < a
			lda z_b
			cmp z_a
			lda z_b+1
			sbc z_a+1
			bcc ntc_cmp_t
			lda #1
			rts
ntc_cmp_ule:					; b >= a
			lda z_b
			cmp z_a
			lda z_b+1
			sbc z_a+1
			bcs ntc_cmp_t
			lda #1
			rts
ntc_cmp_eq:
			lda z_a
			cmp z_b
			bne ntc_cmp_f
			lda z_a+1
			cmp z_b+1
			bne ntc_cmp_f
			lda #0
			rts
ntc_cmp_ne:
			lda z_a
			cmp z_b
			bne ntc_cmp_t
			lda z_a+1
			cmp z_b+1
			bne ntc_cmp_t
			lda #1
			rts
; the operands: vv (two vars), vl (a var, a literal) into z_a, z_b; then jmp (z_g)
ntc_cmp_vv:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p0),y
			sta z_a
			lda (z_p1),y
			sta z_b
			iny
			lda (z_p0),y
			sta z_a+1
			lda (z_p1),y
			sta z_b+1
			jmp (z_g)
ntc_cmp_vl:
			NTC_POP z_p0
			NTC_POP z_b
			ldy #0
			lda (z_p0),y
			sta z_a
			iny
			lda (z_p0),y
			sta z_a+1
			jmp (z_g)

;## kw_scpltvv ntc_cmp
kw_scpltvv:
			lda #<ntc_cmp_slt
			sta z_g
			lda #>ntc_cmp_slt
			sta z_g+1
			jmp ntc_cmp_vv

;## kw_scpltvl ntc_cmp
kw_scpltvl:
			lda #<ntc_cmp_slt
			sta z_g
			lda #>ntc_cmp_slt
			sta z_g+1
			jmp ntc_cmp_vl

;## kw_scplevv ntc_cmp
kw_scplevv:
			lda #<ntc_cmp_sle
			sta z_g
			lda #>ntc_cmp_sle
			sta z_g+1
			jmp ntc_cmp_vv

;## kw_scplevl ntc_cmp
kw_scplevl:
			lda #<ntc_cmp_sle
			sta z_g
			lda #>ntc_cmp_sle
			sta z_g+1
			jmp ntc_cmp_vl

;## kw_scpgtvv ntc_cmp
kw_scpgtvv:
			lda #<ntc_cmp_sgt
			sta z_g
			lda #>ntc_cmp_sgt
			sta z_g+1
			jmp ntc_cmp_vv

;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			lda #<ntc_cmp_sgt
			sta z_g
			lda #>ntc_cmp_sgt
			sta z_g+1
			jmp ntc_cmp_vl

;## kw_scpgevv ntc_cmp
kw_scpgevv:
			lda #<ntc_cmp_sge
			sta z_g
			lda #>ntc_cmp_sge
			sta z_g+1
			jmp ntc_cmp_vv

;## kw_scpgevl ntc_cmp
kw_scpgevl:
			lda #<ntc_cmp_sge
			sta z_g
			lda #>ntc_cmp_sge
			sta z_g+1
			jmp ntc_cmp_vl

;## kw_cpeqvv
kw_cpeqvv:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p0),y
			cmp (z_p1),y
			bne kw_ceq_f
			iny
			lda (z_p0),y
			cmp (z_p1),y
			bne kw_ceq_f
			lda #0
			rts
kw_ceq_f:
			lda #1
			rts

;## kw_cpeqvl
kw_cpeqvl:
			NTC_POP z_p0
			NTC_POP z_b
			ldy #0
			lda (z_p0),y
			cmp z_b
			bne kw_ceql_f
			iny
			lda (z_p0),y
			cmp z_b+1
			bne kw_ceql_f
			lda #0
			rts
kw_ceql_f:
			lda #1
			rts

;## kw_cpnevl ntc_cmp
kw_cpnevl:
			lda #<ntc_cmp_ne
			sta z_g
			lda #>ntc_cmp_ne
			sta z_g+1
			jmp ntc_cmp_vl

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE): 16 bit addresses, the CPU's 64K
; (bank 0, I/O at $D000)
; ============================================================

;## ntc_aidx
; z_p0 = array base, z_p1 = the index var: z_p0 = base + index * 2 (ntc_aidx2),
; base + index (ntc_aidx1), base + index * 4 (ntc_aidx4); then jmp (z_g)
ntc_aidx4:
			ldy #0
			lda (z_p1),y
			sta z_t0
			iny
			lda (z_p1),y
			asl z_t0
			rol
			asl z_t0
			rol
			sta z_t1
			jmp ntc_aidx_add
ntc_aidx2:
			ldy #0
			lda (z_p1),y
			asl
			sta z_t0
			iny
			lda (z_p1),y
			rol
			sta z_t1
			jmp ntc_aidx_add
ntc_aidx1:
			ldy #0
			lda (z_p1),y
			sta z_t0
			iny
			lda (z_p1),y
			sta z_t1
ntc_aidx_add:
			clc
			lda z_p0
			adc z_t0
			sta z_p0
			lda z_p0+1
			adc z_t1
			sta z_p0+1
			jmp (z_g)

;## kw_aget ntc_aidx
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p1),y
			asl
			sta z_t0
			iny
			lda (z_p1),y
			rol
			sta z_t1
			clc
			lda z_p0
			adc z_t0
			sta z_p0
			lda z_p0+1
			adc z_t1
			sta z_p0+1
			NTC_POP z_p1
			ldy #0
			lda (z_p0),y
			sta (z_p1),y
			iny
			lda (z_p0),y
			sta (z_p1),y
			rts

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p1),y
			asl
			sta z_t0
			iny
			lda (z_p1),y
			rol
			sta z_t1
			clc
			lda z_p0
			adc z_t0
			sta z_p0
			lda z_p0+1
			adc z_t1
			sta z_p0+1
			NTC_POP z_p1
			ldy #0
			lda (z_p1),y
			sta (z_p0),y
			iny
			lda (z_p1),y
			sta (z_p0),y
			rts

;## kw_asetl
;kw_asetl, <arraybase>, <indexvar>, <literal>
kw_asetl:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p1),y
			asl
			sta z_t0
			iny
			lda (z_p1),y
			rol
			sta z_t1
			clc
			lda z_p0
			adc z_t0
			sta z_p0
			lda z_p0+1
			adc z_t1
			sta z_p0+1
			NTC_POP z_a
			ldy #0
			lda z_a
			sta (z_p0),y
			iny
			lda z_a+1
			sta (z_p0),y
			rts

;## ntc_rnd_seed
ntc_rnd_seed:	dw 1

;## ntc_rnd ntc_rnd_seed ntc_div
; the next number (z_b = n): 0 .. n-1 into the var next on the thread (0 if n <= 0)
ntc_rnd:
			lda ntc_rnd_seed+1			; h' = ((h & 1) << 7 | l >> 1) xor h
			lsr
			lda ntc_rnd_seed
			ror
			eor ntc_rnd_seed+1
			sta z_t1					; h'
			lda ntc_rnd_seed			; l' = ((l & 1) << 7 | h' >> 1) xor l
			lsr
			lda z_t1
			ror
			eor ntc_rnd_seed
			sta ntc_rnd_seed			; l'
			eor z_t1					; h'' = l' xor h'
			sta ntc_rnd_seed+1
			lda z_b+1
			bmi ntc_rnd_zero
			ora z_b
			beq ntc_rnd_zero
			lda ntc_rnd_seed
			sta z_a
			lda ntc_rnd_seed+1
			and #$7F
			sta z_a+1
			NTC_RS
			jsr ntc_div
			NTC_TS
			NTC_POP z_p0
			ldy #0
			lda z_b
			sta (z_p0),y
			iny
			lda z_b+1
			sta (z_p0),y
			rts
ntc_rnd_zero:
			NTC_POP z_p0
			lda #0
			tay
			sta (z_p0),y
			iny
			sta (z_p0),y
			rts

;## kw_rndl ntc_rnd
;kw_rndl, <literal>, <destvar>
kw_rndl:
			NTC_POP z_b
			jmp ntc_rnd

;## kw_seedv ntc_rnd_seed
;kw_seedv, <var>  - RANDOMIZE var (0 becomes 1)
kw_seedv:
			NTC_POP z_p0
			ldy #0
			lda (z_p0),y
			sta ntc_rnd_seed
			iny
			lda (z_p0),y
			sta ntc_rnd_seed+1
			ora ntc_rnd_seed
			bne kw_sd_ok
			inc ntc_rnd_seed
kw_sd_ok:
			rts

;## ntc_scopy
; z_p0 = source, z_p1 = dest, X = the most characters (0 .. 255): copy, then the 0.
; Ends with rts (callable with JSR, or as a keyword's tail on the thread)
ntc_scopy:
			ldy #0
			cpx #0
			beq ntc_scp_cut
ntc_scp_lp:
			lda (z_p0),y
			sta (z_p1),y
			beq ntc_scp_e
			iny
			dex
			bne ntc_scp_lp
ntc_scp_cut:
			lda #0
			sta (z_p1),y
ntc_scp_e:
			rts
; X = the capacity byte before z_p1 (uses A)
ntc_scap:
			dew z_p1
			ldy #0
			lda (z_p1),y
			tax
			inw z_p1
			rts

;## kw_strcpy ntc_scopy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			NTC_POP z_p1
			NTC_POP z_p0
			dew z_p1
			ldy #0
			lda (z_p1),y
			tax
			inw z_p1
			jmp ntc_scopy

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			NTC_POP z_p1
			NTC_POP z_p0
			dew z_p1
			ldy #0
			lda (z_p1),y
			sta z_t0					; capacity
			inw z_p1
			ldy #0
kw_sc_end:
			cpy z_t0
			bcs kw_sc_full
			lda (z_p1),y
			beq kw_sc_copy
			iny
			bne kw_sc_end
kw_sc_full:
			rts
kw_sc_copy:
			tya							; dest += its length
			clc
			adc z_p1
			sta z_p1
			bcc kw_sc_nc
			inc z_p1+1
kw_sc_nc:
			sty z_t1
			lda z_t0
			sec
			sbc z_t1
			tax							; room left
			ldy #0
			cpx #0
			beq kw_sc_e
kw_sc_lp:
			lda (z_p0),y
			sta (z_p1),y
			beq kw_sc_e
			iny
			dex
			bne kw_sc_lp
			lda #0
			sta (z_p1),y
kw_sc_e:
			rts

;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
kw_sl_lp:
			lda (z_p0),y
			beq kw_sl_e
			iny
			bne kw_sl_lp
kw_sl_e:
			tya
			ldy #0
			sta (z_p1),y
			iny
			lda #0
			sta (z_p1),y
			rts

;## kw_strcmpne
;kw_strcmpne, <addr1>, <addr2>  - Z if not equal
kw_strcmpne:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
kw_sne_lp:
			lda (z_p0),y
			cmp (z_p1),y
			bne kw_sne_t
			cmp #0
			beq kw_sne_f
			iny
			bne kw_sne_lp
kw_sne_f:
			lda #1						; equal: NZ
			rts
kw_sne_t:
			lda #0						; not equal: Z
			rts

; ============================================================
; I/O. The platform's console routines run on the real stack.
; ============================================================

;## ntc_puts ntc_data ntc_plat_screen
; print the 0 terminated text at z_p0 (JSR on the real stack). Uses z_p0
ntc_puts:
			ldy #0
			lda (z_p0),y
			beq ntc_puts_e
			jsr ntc_plat_putc
			inw z_p0
			jmp ntc_puts
ntc_puts_e:
			rts

;## ntc_printbuf ntc_puts
; print the text at z_p0, then rts (the thread). On the thread.
ntc_printbuf:
			NTC_RS
			jsr ntc_puts
			NTC_TS
			rts

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			NTC_POP z_p0
			jmp ntc_printbuf

;## ntc_itoa ntc_data
; z_a = signed value, z_p1 = buffer: the digits and a 0 (z_p1 ends on the 0).
; JSR (the real stack). Uses z_a, z_b, z_c, z_t0
ntc_itoa:
			lda z_a+1
			bpl ntc_ia_pos
			lda #'-'
			ldy #0
			sta (z_p1),y
			inw z_p1
			sec
			lda #0
			sbc z_a
			sta z_a
			lda #0
			sbc z_a+1
			sta z_a+1
ntc_ia_pos:
; z_a unsigned to digits at z_p1
ntc_utoa:
			ldx #0						; digits on the 8 bit stack area: in ntc_ia_tmp
ntc_ia_lp:
			stx z_t0
			lda #10
			sta z_b
			lda #0
			sta z_b+1
			jsr ntc_udiv10
			ldx z_t0
			lda z_c
			ora #'0'
			sta ntc_ia_tmp,x
			inx
			lda z_a
			ora z_a+1
			bne ntc_ia_lp
			ldy #0
ntc_ia_cp:
			dex
			lda ntc_ia_tmp,x
			sta (z_p1),y
			iny
			cpx #0
			bne ntc_ia_cp
			lda #0
			sta (z_p1),y
			tya
			clc
			adc z_p1
			sta z_p1
			bcc ntc_ia_e
			inc z_p1+1
ntc_ia_e:
			rts
; z_a / 10 unsigned: z_a = quotient, z_c = remainder
ntc_udiv10:
			lda #0
			sta z_c
			ldx #16
ntc_u10_lp:
			asl z_a
			rol z_a+1
			rol z_c
			lda z_c
			cmp #10
			bcc ntc_u10_no
			sbc #10
			sta z_c
			inc z_a
ntc_u10_no:
			dex
			bne ntc_u10_lp
			lda #0
			sta z_c+1
			rts
ntc_ia_tmp:	ds 8

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			NTC_POP z_p0
			ldy #0
			lda (z_p0),y
			sta z_a
			iny
			lda (z_p0),y
			sta z_a+1
			lda #<ntc_numbuf
			sta z_p1
			lda #>ntc_numbuf
			sta z_p1+1
			NTC_RS
			jsr ntc_itoa
			lda #<ntc_numbuf
			sta z_p0
			lda #>ntc_numbuf
			sta z_p0+1
			jsr ntc_puts
			NTC_TS
			rts

;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

;## ntc_atoi ntc_data
; text at z_p0 to a number into the var at z_p3 (JSR). Spaces first, then - ,
; then digits (or &H hex). Uses z_a, z_b, z_t0, z_t1
ntc_atoi:
			lda #0
			sta z_a
			sta z_a+1
			sta z_t1					; minus
			ldy #0
ntc_at_sp:
			lda (z_p0),y
			cmp #' '
			bne ntc_at_sg
			iny
			bne ntc_at_sp
ntc_at_sg:
			cmp #'-'
			bne ntc_at_amp
			inc z_t1
			iny
			lda (z_p0),y
ntc_at_amp:
			cmp #'&'
			bne ntc_at_dec
			iny
			lda (z_p0),y
			iny
			ora #$20
			cmp #'h'
			bne ntc_at_done
ntc_at_hex:
			lda (z_p0),y
			iny
			sec
			sbc #'0'
			bcc ntc_at_done
			cmp #10
			bcc ntc_at_hd
			ora #$20					; (letters: lower case, then 'a'-'0' off)
			sec
			sbc #$31					; 'a' - '0' with the $20
			bcc ntc_at_done
			cmp #6
			bcs ntc_at_done
			adc #10
ntc_at_hd:
			sta z_t0
			asl z_a
			rol z_a+1
			asl z_a
			rol z_a+1
			asl z_a
			rol z_a+1
			asl z_a
			rol z_a+1
			lda z_a
			ora z_t0
			sta z_a
			jmp ntc_at_hex
ntc_at_dec:
			lda (z_p0),y
			iny
			sec
			sbc #'0'
			bcc ntc_at_done
			cmp #10
			bcs ntc_at_done
			sta z_t0
			lda z_a						; * 10: (a * 4 + a) * 2
			sta z_b
			lda z_a+1
			sta z_b+1
			asl z_a
			rol z_a+1
			asl z_a
			rol z_a+1
			clc
			lda z_a
			adc z_b
			sta z_a
			lda z_a+1
			adc z_b+1
			sta z_a+1
			asl z_a
			rol z_a+1
			clc
			lda z_a
			adc z_t0
			sta z_a
			bcc ntc_at_dec
			inc z_a+1
			jmp ntc_at_dec
ntc_at_done:
			lda z_t1
			beq ntc_at_st
			sec
			lda #0
			sbc z_a
			sta z_a
			lda #0
			sbc z_a+1
			sta z_a+1
ntc_at_st:
			ldy #0
			lda z_a
			sta (z_p3),y
			iny
			lda z_a+1
			sta (z_p3),y
			rts

;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			NTC_POP z_p2
			NTC_RS
			jsr ntc_plat_scankey
			sta z_t0
			NTC_TS
			ldy #0
			lda z_t0
			sta (z_p2),y
			iny
			lda #0
			sta (z_p2),y
			rts

;## kw_cls ntc_data ntc_plat_screen
kw_cls:
			NTC_RS
			jsr ntc_plat_cls
			NTC_TS
			rts

;## kw_locatell ntc_data ntc_plat_screen
;kw_locatell, <x>, <y>  - 1 based
kw_locatell:
			NTC_POP z_a
			NTC_POP z_b
			NTC_RS
			ldx z_a
			ldy z_b
			lda z_a+1					; (past 255: off the screen)
			ora z_b+1
			bne kw_ll_e
			jsr ntc_plat_locate
kw_ll_e:
			NTC_TS
			rts

;## kw_locatevv ntc_data ntc_plat_screen
;kw_locatevv, <xvar>, <yvar>
kw_locatevv:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p0),y
			sta z_a
			lda (z_p1),y
			sta z_b
			iny
			lda (z_p0),y
			ora (z_p1),y
			sta z_t0
			NTC_RS
			lda z_t0
			bne kw_lv_e
			ldx z_a
			ldy z_b
			jsr ntc_plat_locate
kw_lv_e:
			NTC_TS
			rts

;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - the tick count (frames, 50 or 60 a second)
kw_ticks:
			NTC_POP z_p2
			NTC_RS
			jsr ntc_plat_ticks
			sta z_t0
			stx z_t1
			NTC_TS
			ldy #0
			lda z_t0
			sta (z_p2),y
			iny
			lda z_t1
			sta (z_p2),y
			rts

; ============================================================
; String functions. Numbers are passed as the address of a word.
; Results go to a string buffer. Dest may be the same as the source.
; Most run on the real stack (NTC_RS ... jsr ... NTC_TS).
; ============================================================

;## ntc_getn
; z_p5 = address of a word: A = its value limited to 0 .. 255. Uses Y
ntc_getn:
			ldy #1
			lda (z_p5),y
			bmi ntc_gn_zero
			bne ntc_gn_max
			dey
			lda (z_p5),y
			rts
ntc_gn_max:
			lda #255
			rts
ntc_gn_zero:
			lda #0
			rts

;## ntc_sncpy
; copy up to X chars from z_p0 to z_p1, then the 0 (JSR). Overlapping forward is fine
ntc_sncpy:
			ldy #0
			cpx #0
			beq ntc_sn_end
ntc_sn_lp:
			lda (z_p0),y
			sta (z_p1),y
			beq ntc_sn_z
			iny
			dex
			bne ntc_sn_lp
ntc_sn_end:
			lda #0
			sta (z_p1),y
ntc_sn_z:
			rts
; Y = the length of the text at z_p0 (A = 0)
ntc_slen0:
			ldy #0
ntc_sl0_lp:
			lda (z_p0),y
			beq ntc_sl0_e
			iny
			bne ntc_sl0_lp
ntc_sl0_e:
			rts

;## kw_strright ntc_getn ntc_sncpy
;kw_strright, <dest>, <src>, <nvar>  - Right$(src, n)
kw_strright:
			NTC_POP z_p1
			NTC_POP z_p0
			NTC_POP z_p5
			NTC_RS
			jsr ntc_getn
			sta z_t0					; n
			jsr ntc_slen0				; Y = len
			tya
			sec
			sbc z_t0					; len - n
			bcs kw_sr_skip
			lda #0
kw_sr_skip:
			clc
			adc z_p0
			sta z_p0
			bcc kw_sr_nc
			inc z_p0+1
kw_sr_nc:
			ldx #255
			jsr ntc_sncpy
			NTC_TS
			rts

;## kw_strmid ntc_getn ntc_sncpy
;kw_strmid, <dest>, <src>, <startvar>, <lenvar>  - Mid$(src, start, len)
kw_strmid:
			NTC_POP z_p1
			NTC_POP z_p0
			NTC_POP z_p5
			NTC_RS
			jsr ntc_getn
			NTC_TS
			tax
			beq kw_sm_s1
			dex							; start - 1 chars to skip
kw_sm_s1:
			ldy #0
kw_sm_sk:
			cpx #0
			beq kw_sm_len
			lda (z_p0),y
			beq kw_sm_len
			inw z_p0
			dex
			jmp kw_sm_sk
kw_sm_len:
			NTC_POP z_p5
			NTC_RS
			jsr ntc_getn
			tax
			jsr ntc_sncpy
			NTC_TS
			rts

;## kw_strspace ntc_getn
;kw_strspace, <dest>, <nvar>  - Space$(n)
kw_strspace:
			NTC_POP z_p1
			NTC_POP z_p5
			NTC_RS
			jsr ntc_getn
			NTC_TS
			tax
			lda #' '
; X = count (NTC_STRMAX at most), A = char, z_p1 = dest. rts
ntc_strfill:
			cpx #<NTC_STRMAX
			bcc ntc_sf_ok
			beq ntc_sf_ok
			ldx #<NTC_STRMAX
ntc_sf_ok:
			ldy #0
			cpx #0
			beq ntc_sf_end
ntc_sf_lp:
			sta (z_p1),y
			iny
			dex
			bne ntc_sf_lp
ntc_sf_end:
			lda #0
			sta (z_p1),y
			rts

;## kw_strval ntc_atoi
;kw_strval, <src>, <destvar>  - Val(src): decimal or &H hex
kw_strval:
			NTC_POP z_p0
			NTC_POP z_p3
			NTC_RS
			jsr ntc_atoi
			NTC_TS
			rts

;## kw_strinstr ntc_getn
;kw_strinstr, <startvar>, <s1>, <s2>, <destvar>  - InStr(start, s1, s2)
kw_strinstr:
			NTC_POP z_p5
			NTC_POP z_p0				; s1
			NTC_POP z_p2				; s2
			NTC_RS
			jsr ntc_getn
			bne kw_in_s1
			lda #1
kw_in_s1:
			sta z_t4					; the result if found here (1 based)
			tax
kw_in_adv:
			dex
			beq kw_in_try
			ldy #0
			lda (z_p0),y
			beq kw_in_nf
			inw z_p0
			jmp kw_in_adv
kw_in_try:
			ldy #0
kw_in_cmp:
			lda (z_p2),y
			beq kw_in_found
			cmp (z_p0),y
			bne kw_in_miss
			iny
			bne kw_in_cmp
kw_in_miss:
			ldy #0
			lda (z_p0),y
			beq kw_in_nf
			inw z_p0
			inc z_t4
			jmp kw_in_try
kw_in_nf:
			lda #0
			sta z_t4
kw_in_found:
			NTC_TS
			NTC_POP z_p1
			ldy #0
			lda z_t4
			sta (z_p1),y
			iny
			lda #0
			sta (z_p1),y
			rts

;## kw_l_mov
kw_l_mov:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #3
kw_lmv_lp:
			lda (z_p0),y
			sta (z_p1),y
			dey
			bpl kw_lmv_lp
			rts

;## kw_l_itol
;kw_l_itol, <intvar>, <dest>  - Integer to Long (sign extended)
kw_l_itol:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			lda (z_p0),y
			sta (z_p1),y
			iny
			lda (z_p0),y
			sta (z_p1),y
			ldx #0
			asl
			bcc kw_lit_p
			ldx #$FF
kw_lit_p:
			txa
			iny
			sta (z_p1),y
			iny
			sta (z_p1),y
			rts

;## kw_l_add
kw_l_add:
			NTC_POP z_p0
			NTC_POP z_p1
			NTC_POP z_p2
			ldy #0
			ldx #4
			clc
kw_lad_lp:
			lda (z_p0),y
			adc (z_p1),y
			sta (z_p2),y
			iny
			dex
			bne kw_lad_lp
			rts

;## ntc_lcmp
; the two Longs off the thread into z_l0 (a), z_l1 (b); then a - b: z_t0 = 0 when
; equal, A = the result's high byte with the sign fixed (bit 7 = a < b signed)
ntc_lcmp_ld:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #0
			ldx #4
			sec
			lda #0
			sta z_t0
ntc_lcl_lp:
			lda (z_p0),y
			sbc (z_p1),y
			sta z_l2,y
			iny
			dex
			bne ntc_lcl_lp
			bvc ntc_lcl_v
			eor #$80
ntc_lcl_v:
			sta z_t1					; bit 7 = a < b
			lda z_l2
			ora z_l2+1
			ora z_l2+2
			ora z_l2+3
			sta z_t0					; 0 = equal
			jmp (z_g)
ntc_lcmp_lt:
			lda z_t1
			bmi ntc_lcmp_t
ntc_lcmp_f:
			lda #1
			rts
ntc_lcmp_t:
			lda #0
			rts
ntc_lcmp_ge:
			lda z_t1
			bpl ntc_lcmp_t
			lda #1
			rts
ntc_lcmp_le:
			lda z_t1
			bmi ntc_lcmp_t
			lda z_t0
			beq ntc_lcmp_t
			lda #1
			rts
ntc_lcmp_gt:
			lda z_t1
			bmi ntc_lcmp_f
			lda z_t0
			beq ntc_lcmp_f
			lda #0
			rts
ntc_lcmp_eq:
			lda z_t0
			beq ntc_lcmp_t
			lda #1
			rts
ntc_lcmp_ne:
			lda z_t0
			bne ntc_lcmp_t
			lda #1
			rts

;## kw_l_cpgt ntc_lcmp
kw_l_cpgt:
			lda #<ntc_lcmp_gt
			sta z_g
			lda #>ntc_lcmp_gt
			sta z_g+1
			jmp ntc_lcmp_ld

;## kw_l_cpge ntc_lcmp
kw_l_cpge:
			lda #<ntc_lcmp_ge
			sta z_g
			lda #>ntc_lcmp_ge
			sta z_g+1
			jmp ntc_lcmp_ld

;## kw_l_cpeq ntc_lcmp
kw_l_cpeq:
			lda #<ntc_lcmp_eq
			sta z_g
			lda #>ntc_lcmp_eq
			sta z_g+1
			jmp ntc_lcmp_ld

;## ntc_lmul
; z_l0 * z_l1 -> z_l0 (low 32 bits: the hardware multiplier). JSR or inline
ntc_lmul:
			ldx #3
ntc_lml_lp:
			lda z_l0,x
			sta $D770,x
			lda z_l1,x
			sta $D774,x
			dex
			bpl ntc_lml_lp
			ldx #3
ntc_lml_out:
			lda $D778,x
			sta z_l0,x
			dex
			bpl ntc_lml_out
			rts

;## ntc_ldiv
; z_l0 / z_l1 signed, truncating (JSR): z_l0 = quotient, z_l1 = remainder (the
; dividend's sign). Divide by 0: quotient 0, remainder = dividend. Uses z_l2, z_t0, z_t1
ntc_ldiv:
			lda z_l1
			ora z_l1+1
			ora z_l1+2
			ora z_l1+3
			bne ntc_ld_nz
			ldx #3
ntc_ld_z:
			lda z_l0,x
			sta z_l1,x
			lda #0
			sta z_l0,x
			dex
			bpl ntc_ld_z
			rts
ntc_ld_nz:
			lda z_l0+3
			sta z_t0					; the dividend's sign
			eor z_l1+3
			sta z_t1					; the quotient's
			lda z_l0+3
			bpl ntc_ld_ap
			ldx #z_l0
			jsr ntc_lnegz
ntc_ld_ap:
			lda z_l1+3
			bpl ntc_ld_bp
			ldx #z_l1
			jsr ntc_lnegz
ntc_ld_bp:
			jsr ntc_ludiv
			lda z_t1
			bpl ntc_ld_qp
			ldx #z_l0
			jsr ntc_lnegz
ntc_ld_qp:
			ldx #3
ntc_ld_r:
			lda z_l2,x
			sta z_l1,x
			dex
			bpl ntc_ld_r
			lda z_t0
			bpl ntc_ld_rp
			ldx #z_l1
			jsr ntc_lnegz
ntc_ld_rp:
			rts
; the Long in the base page at X: negated
ntc_lnegz:
			sec
			lda #0
			sbc 0,x
			sta 0,x
			lda #0
			sbc 1,x
			sta 1,x
			lda #0
			sbc 2,x
			sta 2,x
			lda #0
			sbc 3,x
			sta 3,x
			rts
; z_l0 / z_l1 unsigned: z_l0 = quotient, z_l2 = remainder. Uses A, X, Y
ntc_ludiv:
			lda #0
			sta z_l2
			sta z_l2+1
			sta z_l2+2
			sta z_l2+3
			ldx #32
ntc_lud_lp:
			asl z_l0
			rol z_l0+1
			rol z_l0+2
			rol z_l0+3
			rol z_l2
			rol z_l2+1
			rol z_l2+2
			rol z_l2+3
			sec
			lda z_l2
			sbc z_l1
			sta z_t2
			lda z_l2+1
			sbc z_l1+1
			sta z_t3
			lda z_l2+2
			sbc z_l1+2
			sta z_t4
			lda z_l2+3
			sbc z_l1+3
			bcc ntc_lud_no
			sta z_l2+3
			lda z_t4
			sta z_l2+2
			lda z_t3
			sta z_l2+1
			lda z_t2
			sta z_l2
			inc z_l0
ntc_lud_no:
			dex
			bne ntc_lud_lp
			rts

;## ntc_l2args
; two Longs off the thread into z_l0 and z_l1 (on the thread: jmp, back with jmp (z_g))
ntc_l2args:
			NTC_POP z_p0
			NTC_POP z_p1
			ldy #3
ntc_l2a_lp:
			lda (z_p0),y
			sta z_l0,y
			lda (z_p1),y
			sta z_l1,y
			dey
			bpl ntc_l2a_lp
			jmp (z_g)
; z_l0 (ntc_lst0) or z_l1 (ntc_lst1) into the Long whose address is next on the thread
ntc_lst0:
			NTC_POP z_p2
			ldy #3
ntc_ls0_lp:
			lda z_l0,y
			sta (z_p2),y
			dey
			bpl ntc_ls0_lp
			rts
ntc_lst1:
			NTC_POP z_p2
			ldy #3
ntc_ls1_lp:
			lda z_l1,y
			sta (z_p2),y
			dey
			bpl ntc_ls1_lp
			rts

;## kw_l_mul ntc_lmul ntc_l2args
kw_l_mul:
			lda #<kw_lmu_b
			sta z_g
			lda #>kw_lmu_b
			sta z_g+1
			jmp ntc_l2args
kw_lmu_b:
			NTC_RS
			jsr ntc_lmul
			NTC_TS
			jmp ntc_lst0

;## kw_l_div ntc_ldiv ntc_l2args
kw_l_div:
			lda #<kw_ldv_b
			sta z_g
			lda #>kw_ldv_b
			sta z_g+1
			jmp ntc_l2args
kw_ldv_b:
			NTC_RS
			jsr ntc_ldiv
			NTC_TS
			jmp ntc_lst0

;## kw_l_mod ntc_ldiv ntc_l2args
kw_l_mod:
			lda #<kw_lmd_b
			sta z_g
			lda #>kw_lmd_b
			sta z_g+1
			jmp ntc_l2args
kw_lmd_b:
			NTC_RS
			jsr ntc_ldiv
			NTC_TS
			jmp ntc_lst1

;## ntc_ltoa ntc_data
; the Long z_l0 to text at z_p1, a 0 at the end (z_p1 on it). JSR. Uses z_l0-z_l2
ntc_ltoa:
			lda z_l0+3
			bpl ntc_lta_pos
			lda #'-'
			ldy #0
			sta (z_p1),y
			inw z_p1
			ldx #z_l0
			jsr ntc_lnegz_t
ntc_lta_pos:
			ldx #0
ntc_lta_lp:
			stx z_t6
			; z_l0 / 10: remainder in A
			lda #0
			sta z_t5
			ldy #32
ntc_lta_dv:
			asl z_l0
			rol z_l0+1
			rol z_l0+2
			rol z_l0+3
			rol z_t5
			lda z_t5
			cmp #10
			bcc ntc_lta_n
			sbc #10
			sta z_t5
			inc z_l0
ntc_lta_n:
			dey
			bne ntc_lta_dv
			ldx z_t6
			lda z_t5
			ora #'0'
			sta ntc_lta_tmp,x
			inx
			lda z_l0
			ora z_l0+1
			ora z_l0+2
			ora z_l0+3
			bne ntc_lta_lp
			ldy #0
ntc_lta_cp:
			dex
			lda ntc_lta_tmp,x
			sta (z_p1),y
			iny
			cpx #0
			bne ntc_lta_cp
			lda #0
			sta (z_p1),y
			tya
			clc
			adc z_p1
			sta z_p1
			bcc ntc_lta_e
			inc z_p1+1
ntc_lta_e:
			rts
ntc_lnegz_t:
			sec
			lda #0
			sbc 0,x
			sta 0,x
			lda #0
			sbc 1,x
			sta 1,x
			lda #0
			sbc 2,x
			sta 2,x
			lda #0
			sbc 3,x
			sta 3,x
			rts
ntc_lta_tmp:	ds 12

;## kw_l_print ntc_ltoa ntc_printbuf
kw_l_print:
			NTC_POP z_p0
			ldy #3
kw_lpr_ld:
			lda (z_p0),y
			sta z_l0,y
			dey
			bpl kw_lpr_ld
			lda #<ntc_numbuf
			sta z_p1
			lda #>ntc_numbuf
			sta z_p1+1
			NTC_RS
			jsr ntc_ltoa
			lda #<ntc_numbuf
			sta z_p0
			lda #>ntc_numbuf
			sta z_p0+1
			jsr ntc_puts
			NTC_TS
			rts

;## kw_l_cstr ntc_ltoa
kw_l_cstr:
			NTC_POP z_p1
			NTC_POP z_p0
			ldy #3
kw_lcs_ld:
			lda (z_p0),y
			sta z_l0,y
			dey
			bpl kw_lcs_ld
			NTC_RS
			jsr ntc_ltoa
			NTC_TS
			rts

;## kw_bssinit ntc_data ntc_plat_screen ntc_plat_exit
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the program (not in its file). Check they end below the I/O area ($D000), then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			NTC_POP z_p0
			NTC_POP z_a
			clc
			lda z_p0
			adc z_a
			sta z_t0
			lda z_p0+1
			adc z_a+1
			bcs kw_bs_big
			cmp #$D0
			bcc kw_bs_ok
			bne kw_bs_big
			lda z_t0
			bne kw_bs_big
kw_bs_ok:
			jmp ntc_zerofill_b
kw_bs_big:
			NTC_RS
			lda #<kw_bs_txt
			sta z_p0
			lda #>kw_bs_txt
			sta z_p0+1
kw_bs_pl:
			ldy #0
			lda (z_p0),y
			beq kw_bs_stop
			jsr ntc_plat_putc
			inw z_p0
			jmp kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp ntc_plat_exit_stop
kw_bs_txt:	db "Not enough memory for the arrays", 0
; z_p0 = start, z_a = bytes: zero them, then rts (the thread)
ntc_zerofill_b:
			lda #0
			ldx z_a+1
			beq ntc_zfb_part
			ldy #0
ntc_zfb_page:
			sta (z_p0),y
			iny
			bne ntc_zfb_page
			inc z_p0+1
			dex
			bne ntc_zfb_page
ntc_zfb_part:
			ldy z_a
			beq ntc_zfb_end
			ldy #0
ntc_zfb_lp:
			sta (z_p0),y
			iny
			cpy z_a
			bne ntc_zfb_lp
ntc_zfb_end:
			rts

;## ntc_plat_data
VIC_SCRA	equ $0800		; graphics: the screen memory showing buffer A (and the console's)
VIC_SCRB	equ $1000		; showing buffer B
VIC_TXT		equ $1800		; graphics: the text layer's characters (40 x 25)
VIC_TCOL	equ $1C00		; its colours
VIC_DIRTY	equ $E800		; its cells to draw again: bit 0 into buffer A, bit 1 into B
ntc_vic_on:		db 0			; $80 = the graphics screen is on (Print goes to its text layer)
ntc_vic_pen:	db 1			; graphics: the text's colour (palette index)
ntc_curx:		db 0			; the cursor (0 based)
ntc_cury:		db 0
ntc_scols:		db 80			; the screen's size
ntc_srows:		db 25
ntc_ticks:		dw 0			; frames since the start (the frame counter, followed)
ntc_m65_lfc:	db 0			; $D7FA last time it was looked at
ntc_m65_brkpc:	dw 0			; BRK: the stack pointer then
ntc_m65_bkx:	db 0
ntc_m65_colour:	db 1			; the console's colour (white)
ntc_m65_logn:	dw 0			; NTC_M65LOG: the log's length

;## ntc_plat_screen ntc_plat_data ntc_data ntc_m65_far
; ------------------------------------------------------------
; the console: screen memory $0800 (ASCII), colours in colour RAM. JSR on
; the real stack; A, X, Y and the platform's base page ($50-$6F) are used.
; ------------------------------------------------------------
; ntc_plat_putc - A = character (32-126; others are shown as they are)
ntc_plat_putc:
			sta ntc_m65_ch
			ifd NTC_M65LOG
			jsr ntc_m65_log
			endif
			bit ntc_vic_on
			bpl ntc_m65_pc_txt
			jsr ntc_m65_txtcell			; graphics: into the text layer
			ldy #0
			lda ntc_m65_ch
			sta ($50),y
			lda ntc_vic_pen
			sta ($52),y
			lda #3
			sta ($54),y
			jmp ntc_m65_pc_adv
ntc_m65_pc_txt:
			jsr ntc_m65_rowaddr			; $50 = the row's address
			ldy ntc_curx
			lda ntc_m65_ch
			sta ($50),y
ntc_m65_pc_adv:
			inc ntc_curx
			lda ntc_curx
			cmp ntc_scols
			bcc ntc_m65_pc_e
			lda #0						; past the end: the next line
			sta ntc_curx
			jmp ntc_m65_down
ntc_m65_pc_e:
			rts

; ntc_plat_newline
ntc_plat_newline:
			ifd NTC_M65LOG
			lda #10
			jsr ntc_m65_log
			endif
			lda #0
			sta ntc_curx
; the cursor down a line, the screen up at the bottom
ntc_m65_down:
			lda ntc_cury
			clc
			adc #1
			cmp ntc_srows
			bcs ntc_m65_dn_end
			sta ntc_cury
			rts
ntc_m65_dn_end:
			bit ntc_vic_on				; graphics: no scrolling (the last row again)
			bpl ntc_m65_scroll
			rts
ntc_m65_scroll:
			; rows 1 .. n-1 up a row (screen memory, then a blank last row)
			lda #<$0800
			sta $50
			lda #>$0800
			sta $51
			lda ntc_scols
			clc
			adc #<$0800
			sta $52
			lda #>$0800
			adc #0
			sta $53
			ldx ntc_srows
			dex
ntc_m65_scr_r:
			ldy #0
ntc_m65_scr_c:
			lda ($52),y
			sta ($50),y
			iny
			cpy ntc_scols
			bne ntc_m65_scr_c
			lda $52
			sta $50
			lda $53
			sta $51
			lda $52
			clc
			adc ntc_scols
			sta $52
			bcc ntc_m65_scr_n
			inc $53
ntc_m65_scr_n:
			dex
			bne ntc_m65_scr_r
			ldy #0
			lda #' '
ntc_m65_scr_b:
			sta ($50),y
			iny
			cpy ntc_scols
			bne ntc_m65_scr_b
			rts

; $50/$51 = the address of the cursor's row in screen memory
ntc_m65_rowaddr:
			lda #<$0800
			sta $50
			lda #>$0800
			sta $51
			ldx ntc_cury
			beq ntc_m65_ra_e
ntc_m65_ra_l:
			lda $50
			clc
			adc ntc_scols
			sta $50
			bcc ntc_m65_ra_n
			inc $51
ntc_m65_ra_n:
			dex
			bne ntc_m65_ra_l
ntc_m65_ra_e:
			rts

; $50 = the text layer's cell at the cursor, $52 its colour, $54 its dirty flags
ntc_m65_txtcell:
			lda ntc_cury				; * 40 = * 32 + * 8
			sta $50
			lda #0
			sta $51
			asl $50
			rol $51
			asl $50
			rol $51
			asl $50
			rol $51
			lda $50
			sta $52
			lda $51
			sta $53						; * 8
			asl $50
			rol $51
			asl $50
			rol $51						; * 32
			clc
			lda $50
			adc $52
			sta $50
			lda $51
			adc $53
			sta $51
			clc
			lda $50
			adc ntc_curx
			sta $50
			sta $52
			sta $54
			lda $51
			adc #0
			sta $51						; the cell's number (the three tables are page aligned)
			clc
			adc #>VIC_TCOL
			sta $53
			lda $51
			clc
			adc #>VIC_DIRTY
			sta $55
			lda $51
			clc
			adc #>VIC_TXT
			sta $51
			rts

; ntc_plat_backspace - back a character and blank it
ntc_plat_backspace:
			lda ntc_curx
			beq ntc_m65_bs_up
			dec ntc_curx
			jmp ntc_m65_bs_blank
ntc_m65_bs_up:
			lda ntc_cury
			beq ntc_m65_bs_e
			dec ntc_cury
			ldx ntc_scols
			dex
			stx ntc_curx
ntc_m65_bs_blank:
			bit ntc_vic_on
			bpl ntc_m65_bs_t
			jsr ntc_m65_txtcell
			ldy #0
			lda #' '
			sta ($50),y
			lda #3
			sta ($54),y
			rts
ntc_m65_bs_t:
			jsr ntc_m65_rowaddr
			ldy ntc_curx
			lda #' '
			sta ($50),y
ntc_m65_bs_e:
			rts

; ntc_plat_cls - blank screen, colours set, cursor home
ntc_plat_cls:
			bit ntc_vic_on
			bpl ntc_m65_cls_t
			ldx #0						; graphics: the text layer blank (a cell that had a
ntc_m65_cls_g:							; character is drawn again: as a space)
			lda VIC_TXT,x
			cmp #' '
			beq ntc_m65_cls_g1
			lda #3
			sta VIC_DIRTY,x
			lda #' '
			sta VIC_TXT,x
ntc_m65_cls_g1:
			lda VIC_TXT+$100,x
			cmp #' '
			beq ntc_m65_cls_g2
			lda #3
			sta VIC_DIRTY+$100,x
			lda #' '
			sta VIC_TXT+$100,x
ntc_m65_cls_g2:
			lda VIC_TXT+$200,x
			cmp #' '
			beq ntc_m65_cls_g3
			lda #3
			sta VIC_DIRTY+$200,x
			lda #' '
			sta VIC_TXT+$200,x
ntc_m65_cls_g3:
			lda VIC_TXT+$300,x
			cmp #' '
			beq ntc_m65_cls_g4
			lda #3
			sta VIC_DIRTY+$300,x
			lda #' '
			sta VIC_TXT+$300,x
ntc_m65_cls_g4:
			inx
			bne ntc_m65_cls_g
			lda #0
			sta ntc_curx
			sta ntc_cury
			rts
ntc_m65_cls_t:
			lda #<$0800
			sta $50
			lda #>$0800
			sta $51
			ldx #8						; 8 x 256 = 2048 bytes (80 x 25 = 2000)
			ldy #0
			lda #' '
ntc_m65_cls_l:
			sta ($50),y
			iny
			bne ntc_m65_cls_l
			inc $51
			dex
			bne ntc_m65_cls_l
			; colour RAM ($FF80000): 2000 bytes of the console's colour
			lda #$00
			sta $54
			lda #$00
			sta $55
			lda #$F8
			sta $56
			lda #$0F
			sta $57
			ldx #8
			ldz #0
			lda ntc_m65_colour
ntc_m65_cls_c:
			sta [$54],z
			inz
			bne ntc_m65_cls_c
			inc $55
			dex
			bne ntc_m65_cls_c
			ldz #0
			lda #0
			sta ntc_curx
			sta ntc_cury
			rts

; ntc_plat_mode - A = mode: 2 = 80 columns, else 40; clears the screen
ntc_plat_mode:
			ldx #0						; (the graphics screen off: Mode is the console's)
			stx ntc_vic_on
			ldx #80
			cmp #2
			beq ntc_m65_md80
			ldx #40
ntc_m65_md80:
			stx ntc_scols
			stx $07F0
			lda #25
			sta ntc_srows
			sta $07F1
			lda #$47					; (in case a program changed the I/O mode)
			sta $D02F
			lda #$53
			sta $D02F
			lda #$80					; PAL (50 frames a second)
			trb $D06F
			lda #$80					; hot registers on while the legacy ones are set
			tsb $D05D
			lda #$1B					; text, display on, 25 rows
			sta $D011
			lda #$C8					; 40 / 80 columns (80: scroll 1 - the VIC-III puts 80
			cpx #80						; column text 2 pixels left of the border)
			bne ntc_m65_md16
			lda #$C9
ntc_m65_md16:
			sta $D016
			lda #$14
			sta $D018
			lda #$40					; FAST, 80 columns when asked
			cpx #80
			bne ntc_m65_md40
			ora #$80
ntc_m65_md40:
			sta $D031
			lda #$40					; VFAST, 8 bit characters (CHR16 / FCLR off)
			sta $D054
			lda #$80					; hot registers off: the precise pointers stay
			trb $D05D
			lda #<$0800					; screen memory
			sta $D060
			lda #>$0800
			sta $D061
			lda #0
			sta $D062
			lda $D063
			and #$F0
			sta $D063
			lda #<$E000					; the font
			sta $D068
			lda #>$E000
			sta $D069
			lda #0
			sta $D06A
			lda #0						; colours from the start of colour RAM
			sta $D064
			sta $D065
			jmp ntc_plat_cls

; ntc_plat_locate - X = column, Y = row (1 based; off the screen: not moved)
ntc_plat_locate:
			dex
			cpx ntc_scols
			bcs ntc_m65_loc_e
			dey
			cpy ntc_srows
			bcs ntc_m65_loc_e
			stx ntc_curx
			sty ntc_cury
ntc_m65_loc_e:
			rts

			ifd NTC_M65LOG
; the log (test builds): A appended at $10000 + its length (bank 1), the length at $1FFFC
ntc_m65_log:
			pha
			lda ntc_m65_logn
			sta $58
			lda ntc_m65_logn+1
			sta $59
			lda #1
			sta $5A
			lda #0
			sta $5B
			pla
			ldz #0
			sta [$58],z
			inc ntc_m65_logn
			bne ntc_m65_logend
			inc ntc_m65_logn+1
ntc_m65_logend:
			lda #<$FFFC
			sta $58
			lda #>$FFFC
			sta $59
			lda #1
			sta $5A
			lda #0
			sta $5B
			ldz #0
			lda ntc_m65_logn
			sta [$58],z
			inz
			lda ntc_m65_logn+1
			sta [$58],z
			inz
			lda #0
			sta [$58],z
			ldz #0
			rts
			endif

;## ntc_m65_far
; (the 32 bit pointers in the base page: $54-$57 colour RAM, $58-$5B the log)
ntc_m65_ch:		db 0

;## ntc_plat_key ntc_plat_data ntc_plat_ticks
; ------------------------------------------------------------
; the keyboard: the hardware's ASCII queue ($D610)
; ------------------------------------------------------------
; ntc_plat_scankey - A = a key typed (taken from the queue) or 0, no wait
ntc_plat_scankey:
			jsr ntc_plat_ticks			; (keeps Ticks going in a key loop)
			lda $D610
			beq ntc_m65_sk_e
			sta $D610					; (any write takes it off the queue)
			cmp #20						; DEL
			bne ntc_m65_sk1
			lda #8
			rts
ntc_m65_sk1:
			cmp #145					; cursor up
			bne ntc_m65_sk2
			lda #$F0
			rts
ntc_m65_sk2:
			cmp #17						; down
			bne ntc_m65_sk3
			lda #$F1
			rts
ntc_m65_sk3:
			cmp #157					; left
			bne ntc_m65_sk4
			lda #$F2
			rts
ntc_m65_sk4:
			cmp #29						; right
			bne ntc_m65_sk_e
			lda #$F3
ntc_m65_sk_e:
			rts

; ntc_plat_getkey - A = the next key (waits)
ntc_plat_getkey:
			jsr ntc_plat_scankey
			cmp #0
			beq ntc_plat_getkey
			rts

;## ntc_plat_ticks ntc_plat_data
; ntc_plat_ticks - the frame counter followed into ntc_ticks: A = low, X = high
ntc_plat_ticks:
			lda $D7FA
			tax
			sec
			sbc ntc_m65_lfc
			stx ntc_m65_lfc
			clc
			adc ntc_ticks
			sta ntc_ticks
			bcc ntc_m65_tk_e
			inc ntc_ticks+1
ntc_m65_tk_e:
			lda ntc_ticks
			ldx ntc_ticks+1
			rts

;## ntc_plat_frame ntc_plat_ticks
; ntc_plat_frame - wait for the next frame (the frame counter moving on)
ntc_plat_frame:
			jsr ntc_plat_ticks
			lda $D7FA
ntc_m65_fr_w:
			cmp $D7FA
			beq ntc_m65_fr_w
			jmp ntc_plat_ticks

;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - End: the console stays, the end marked for the test tools
ntc_plat_exit:
			lda #$A5
			sta $07F2
			rts
ntc_plat_exit_stop:
			jsr ntc_plat_exit
ntc_m65_halt:
			jmp ntc_m65_halt

;## ntc_vic ntc_plat_data ntc_plat_screen ntc_plat_frame ntc_m65_far
; ------------------------------------------------------------
; The graphics screen (the Vic class): 320 x 200, 256 colours, two buffers.
; Each buffer is 1000 full colour characters (64 bytes each, a pixel a byte):
; buffer A at $40000 (characters $1000-$13E7, shown by screen memory $0800),
; buffer B at $50000 ($1400-$17E7, screen memory $1000). Character (column c,
; row r) is c * 25 + r, so a column of 8 pixels runs down the screen without a
; break: pixel (x, y) is at (x >> 3) * 1600 + y * 8 + (x & 7).
; Vic.Update draws the next picture into the buffer not shown - the playfield
; (columns 0 .. ntc_vic_fw - 1) cleared, the stars, the sprites (79 first, so
; sprite 0 is in front), the text layer - then waits for the frame and shows it.
; The panel (columns ntc_vic_fw .. 39) is not cleared: its text is drawn when it
; changes (into each buffer once), opaque, and Vic.Stamp / Vic.Box draw into both.
; Images: w, h (pixels, h even, 32 at most), then w columns of h / 2 bytes: two
; pixels a byte (the low nibble the upper), 0 = clear, 1-15 = colour + the
; sprite's palette * 16 + 16.
; Sprites (8 bytes each): x (16 bits, signed), y, image, attributes (bit 0 flip
; x, bit 1 flip y, bits 4-5 the palette), shown (0 / 1), 0.
; Uses $50-$6F (the platform's base page).
; ------------------------------------------------------------
VIC_NSPR	equ 80
ntc_vic_fw:		db 32			; the playfield's width in columns (8 pixels)
ntc_vic_fpx:	dw 256			; ... in pixels
ntc_vic_back:	db 1			; the buffer being drawn: 0 A, 1 B
ntc_vic_bg:		db 0			; the playfield's colour
ntc_vic_paper:	db 0			; the panel text's background
ntc_vic_imgs:	dw 0			; the image table: an address for each image
ntc_vic_starn:	db 0			; stars
ntc_vic_spn:	db 0			; (the sprite loop's count)
ntc_vic_noflip:	db 0			; 1: Vic.Draw (drawn into the back buffer, not shown)
ntc_vic_stary:	db 0			; their scroll (added to each star's y)
ntc_vic_sat:	ds VIC_NSPR*8
ntc_vic_sx:		ds 64			; the stars: x, y, colour
ntc_vic_sy:		ds 64
ntc_vic_sc:		ds 64
; the columns' offsets: c * 1600
ntc_vic_cbl:	db <0, <1600, <3200, <4800, <6400, <8000, <9600, <11200, <12800, <14400
				db <16000, <17600, <19200, <20800, <22400, <24000, <25600, <27200, <28800, <30400
				db <32000, <33600, <35200, <36800, <38400, <40000, <41600, <43200, <44800, <46400
				db <48000, <49600, <51200, <52800, <54400, <56000, <57600, <59200, <60800, <62400, <64000
ntc_vic_cbh:	db >0, >1600, >3200, >4800, >6400, >8000, >9600, >11200, >12800, >14400
				db >16000, >17600, >19200, >20800, >22400, >24000, >25600, >27200, >28800, >30400
				db >32000, >33600, >35200, >36800, >38400, >40000, >41600, >43200, >44800, >46400
				db >48000, >49600, >51200, >52800, >54400, >56000, >57600, >59200, >60800, >62400, >64000
; a DMA fill job (F018B, enhanced): count, the byte, the destination
ntc_vic_dmal:
			db $0B						; F018B
			db $81, $00					; destination MB 0
			db $00						; end of options
			db $03						; fill
ntc_vic_dmac:	dw 0				; count
ntc_vic_dmav:	db 0, 0				; the byte (the source's low byte)
			db 0						; source bank
ntc_vic_dmad:	dw 0				; destination
ntc_vic_dmab:	db 4				; destination bank
			db 0						; command (high)
			dw 0						; modulo

; ntc_vic_fill - DMA fill: $5C/$5D = the start (in the bank), $5E/$5F = bytes, A = the
; byte, X = the bank
ntc_vic_fill:
			sta ntc_vic_dmav
			stx ntc_vic_dmab
			lda $5C
			sta ntc_vic_dmad
			lda $5D
			sta ntc_vic_dmad+1
			lda $5E
			sta ntc_vic_dmac
			lda $5F
			sta ntc_vic_dmac+1
			ora $5E
			beq ntc_vic_fl_e
			lda #0
			sta $D702					; the job's bank and MB
			sta $D704
			lda #>ntc_vic_dmal
			sta $D701
			lda #<ntc_vic_dmal
			sta $D705					; go (enhanced)
ntc_vic_fl_e:
			rts

; ntc_vic_screen - A = 1: the graphics screen on (both buffers cleared, the text layer
; blank), 0: off (the console, 80 columns)
ntc_vic_screen:
			cmp #0
			bne ntc_vic_son
			lda #2
			jmp ntc_plat_mode
ntc_vic_son:
			lda #$47
			sta $D02F
			lda #$53
			sta $D02F
			; the screen memories: cell (c, r) at (r * 40 + c) * 2 = $1000 / $1400 + c * 25 + r
			lda #<VIC_SCRA
			sta $50
			lda #>VIC_SCRA
			sta $51
			lda #<VIC_SCRB
			sta $52
			lda #>VIC_SCRB
			sta $53
			lda #0
			sta $56						; row
ntc_vic_sm_r:
			lda $56						; the row's first character: $1000 + r
			sta $58
			lda #$10
			sta $59
			ldx #40
			ldy #0
ntc_vic_sm_c:
			lda $58
			sta ($50),y
			sta ($52),y
			iny
			lda $59
			sta ($50),y
			clc
			adc #4						; buffer B: + $400
			sta ($52),y
			iny
			clc
			lda $58
			adc #25
			sta $58
			bcc ntc_vic_sm_n
			inc $59
ntc_vic_sm_n:
			dex
			bne ntc_vic_sm_c
			clc							; the next row: + 80 bytes
			lda $50
			adc #80
			sta $50
			bcc ntc_vic_sm_1
			inc $51
ntc_vic_sm_1:
			clc
			lda $52
			adc #80
			sta $52
			bcc ntc_vic_sm_2
			inc $53
ntc_vic_sm_2:
			inc $56
			lda $56
			cmp #25
			bne ntc_vic_sm_r
			; colour RAM: 2000 bytes of 0
			lda #$00
			sta $54
			sta $55
			lda #$F8
			sta $56
			lda #$0F
			sta $57
			ldx #8
			ldz #0
			lda #0
ntc_vic_cr:
			sta [$54],z
			inz
			bne ntc_vic_cr
			inc $55
			dex
			bne ntc_vic_cr
			ldz #0
			; both buffers cleared
			lda #0
			sta $5C
			sta $5D
			lda #<64000
			sta $5E
			lda #>64000
			sta $5F
			lda ntc_vic_bg
			ldx #4
			jsr ntc_vic_fill
			lda ntc_vic_bg
			ldx #5
			jsr ntc_vic_fill
			; no sprites, no stars, the text layer blank
			ldx #0
			txa
ntc_vic_sc0:
			sta ntc_vic_sat,x
			sta ntc_vic_sat+$100,x
			inx
			bne ntc_vic_sc0
ntc_vic_sc1:
			sta ntc_vic_sat+$200,x
			inx
			cpx #<(VIC_NSPR*8-$200)
			bne ntc_vic_sc1
			sta ntc_vic_starn
			lda #$80
			sta ntc_vic_on
			lda #40
			sta ntc_scols
			sta $07F0
			lda #25
			sta ntc_srows
			sta $07F1
			ldx #0						; the text layer: spaces, nothing to draw
ntc_vic_tl:
			lda #' '
			sta VIC_TXT,x
			sta VIC_TXT+$100,x
			sta VIC_TXT+$200,x
			sta VIC_TXT+$300,x
			lda #0
			sta VIC_DIRTY,x
			sta VIC_DIRTY+$100,x
			sta VIC_DIRTY+$200,x
			sta VIC_DIRTY+$300,x
			inx
			bne ntc_vic_tl
			stx ntc_curx
			stx ntc_cury
			; the VIC-IV: 40 columns, 16 bit characters, full colour above 255
			lda #$80					; PAL
			trb $D06F
			lda #$80
			tsb $D05D
			lda #$1B
			sta $D011
			lda #$C8
			sta $D016
			lda #$14
			sta $D018
			lda #$40					; FAST, 40 columns
			sta $D031
			lda #$45					; VFAST, CHR16, FCLRHI
			sta $D054
			lda #$80
			trb $D05D
			lda #80						; 80 bytes a row (40 x 2)
			sta $D058
			lda #0
			sta $D059
			lda #40
			sta $D05E
			lda #<VIC_SCRA				; showing A, drawing B
			sta $D060
			lda #>VIC_SCRA
			sta $D061
			lda #0
			sta $D062
			lda $D063
			and #$C0
			sta $D063
			lda #0
			sta $D064
			sta $D065
			lda #1
			sta ntc_vic_back
			rts

; ntc_vic_color - X = the colour (0-255), $5E/$5F = &HRGB (4 bits each)
ntc_vic_color:
			lda $5F						; red: 0R -> RR (the register: the nybbles swapped,
			and #$0F					; the same for RR)
			sta $5D
			asl
			asl
			asl
			asl
			ora $5D
			sta $D100,x
			lda $5E						; green: G0
			and #$F0
			sta $5D
			lsr
			lsr
			lsr
			lsr
			ora $5D
			sta $D200,x
			lda $5E						; blue: 0B
			and #$0F
			sta $5D
			asl
			asl
			asl
			asl
			ora $5D
			sta $D300,x
			rts

; ntc_vic_update - the next picture into the buffer not shown, then shown at the frame
ntc_vic_update:
			lda ntc_vic_back
			clc
			adc #4
			sta $6C						; the bank being drawn
			sta $52
			lda #0
			sta $53
			; the playfield cleared
			sta $5C
			sta $5D
			ldx ntc_vic_fw
			lda ntc_vic_cbl,x
			sta $5E
			lda ntc_vic_cbh,x
			sta $5F
			lda ntc_vic_bg
			ldx $6C
			jsr ntc_vic_fill
			jsr ntc_vic_stars
			jsr ntc_vic_sprites
			jsr ntc_vic_text
			lda ntc_vic_noflip
			beq ntc_vic_u_show
			rts							; (Vic.Draw: drawn, not shown)
ntc_vic_u_show:
			; shown at the next frame
			jsr ntc_plat_frame
			lda ntc_vic_back
			bne ntc_vic_u_b
			lda #<VIC_SCRA
			sta $D060
			lda #>VIC_SCRA
			sta $D061
			lda #1
			sta ntc_vic_back
			rts
ntc_vic_u_b:
			lda #<VIC_SCRB
			sta $D060
			lda #>VIC_SCRB
			sta $D061
			lda #0
			sta ntc_vic_back
			rts

; the stars: pixels at (x, y + scroll) within the playfield
ntc_vic_stars:
			ldx ntc_vic_starn
			beq ntc_vic_st_e
			dex
ntc_vic_st_l:
			lda ntc_vic_sy,x
			clc
			adc ntc_vic_stary
			cmp #200
			bcs ntc_vic_st_n
			sta $50						; y * 8
			lda #0
			sta $51
			asl $50
			rol $51
			asl $50
			rol $51
			asl $50
			rol $51
			lda ntc_vic_sx,x
			sta $5C
			lda ntc_vic_fpx+1			; x < the playfield's width
			bne ntc_vic_st_ok
			lda $5C
			cmp ntc_vic_fpx
			bcs ntc_vic_st_n
ntc_vic_st_ok:
			lda $5C
			and #7
			clc
			adc $50
			sta $50
			bcc ntc_vic_st_1
			inc $51
ntc_vic_st_1:
			lda $5C
			lsr
			lsr
			lsr
			tay
			clc
			lda $50
			adc ntc_vic_cbl,y
			sta $50
			lda $51
			adc ntc_vic_cbh,y
			sta $51
			ldz #0
			lda ntc_vic_sc,x
			sta [$50],z
ntc_vic_st_n:
			dex
			bpl ntc_vic_st_l
ntc_vic_st_e:
			rts

; the sprites, 79 down to 0
ntc_vic_sprites:
			lda #<(ntc_vic_sat+(VIC_NSPR-1)*8)
			sta $6A
			lda #>(ntc_vic_sat+(VIC_NSPR-1)*8)
			sta $6B
			lda #VIC_NSPR
			sta ntc_vic_spn
ntc_vic_sp_l:
			ldy #6
			lda ($6A),y
			beq ntc_vic_sp_n
			ldy #0
			lda ($6A),y
			sta $62
			iny
			lda ($6A),y
			sta $63
			iny
			lda ($6A),y
			sta $64
			iny
			lda ($6A),y
			sta $65
			iny
			lda ($6A),y					; the image
			asl
			tax
			iny
			lda ($6A),y					; attributes
			sta $69
			and #$30
			clc
			adc #16
			sta $68						; the colour added to each pixel
			txa							; the image's address from the table
			clc
			adc ntc_vic_imgs
			sta $5E
			lda ntc_vic_imgs+1
			adc #0
			sta $5F
			ldy #0
			lda ($5E),y
			sta $60
			iny
			lda ($5E),y
			sta $61
			jsr ntc_vic_draw
ntc_vic_sp_n:
			sec
			lda $6A
			sbc #8
			sta $6A
			bcs ntc_vic_sp_1
			dec $6B
ntc_vic_sp_1:
			dec ntc_vic_spn
			bne ntc_vic_sp_l
			rts

; ntc_vic_draw - the image at $60 to $62 (x), $64 (y): $68 = colour added, $69 = flips,
; $6C = the bank. Clipped to the playfield (x) and the screen (y)
ntc_vic_draw:
			ldy #0
			lda ($60),y
			sta $66						; w
			iny
			lda ($60),y
			sta $67						; h
			lsr
			sta $6E						; bytes a column
			clc							; the pixels
			lda $60
			adc #2
			sta $5C
			lda $61
			adc #0
			sta $5D
			; off the screen? y >= 200 or y + h <= 0, x >= field or x + w <= 0
			lda $65
			bmi ntc_vic_dr_yneg
			bne ntc_vic_dr_e
			lda $64
			cmp #200
			bcs ntc_vic_dr_e
			clc
			adc $67
			bcs ntc_vic_dr_y0			; past 255: past the bottom
			cmp #201
			lda #0
			bcc ntc_vic_dr_y1
ntc_vic_dr_y0:
			lda #1						; reaches past the bottom: clip
ntc_vic_dr_y1:
			sta $6F
			jmp ntc_vic_dr_x
ntc_vic_dr_yneg:
			clc
			lda $64
			adc $67
			tax
			lda $65
			adc #0
			bmi ntc_vic_dr_e
			bne ntc_vic_dr_yc
			cpx #0
			beq ntc_vic_dr_e
ntc_vic_dr_yc:
			lda #1
			sta $6F
ntc_vic_dr_x:
			lda $63						; x >= field (x signed)
			bmi ntc_vic_dr_xneg
			cmp ntc_vic_fpx+1
			bcc ntc_vic_dr_cols
			bne ntc_vic_dr_e
			lda $62
			cmp ntc_vic_fpx
			bcs ntc_vic_dr_e
			jmp ntc_vic_dr_cols
ntc_vic_dr_xneg:
			clc							; x + w <= 0
			lda $62
			adc $66
			lda $63
			adc #0
			bmi ntc_vic_dr_e
ntc_vic_dr_cols:
			; all of it on the screen (no clipping): the fast way
			lda $6F
			bne ntc_vic_dr_slow
			lda $63
			bmi ntc_vic_dr_slow
			clc							; x + w <= field
			lda $62
			adc $66
			tax
			lda $63
			adc #0
			cmp ntc_vic_fpx+1
			bcc ntc_vic_fast
			bne ntc_vic_dr_slow
			cpx ntc_vic_fpx
			bcc ntc_vic_fast
			beq ntc_vic_fast
ntc_vic_dr_slow:
			lda #0
			sta $6D						; the column (counts up)
ntc_vic_dr_c:
			; sx = x + c (flip x: x + w - 1 - c)
			lda $69
			and #1
			bne ntc_vic_dr_fx
			clc
			lda $62
			adc $6D
			sta $56
			lda $63
			adc #0
			sta $57
			jmp ntc_vic_dr_sx
ntc_vic_dr_fx:
			lda $66
			sec
			sbc #1
			sec
			sbc $6D
			clc
			adc $62
			sta $56
			lda $63
			adc #0
			sta $57
ntc_vic_dr_sx:
			lda $57						; 0 <= sx < field (16 bits)
			bmi ntc_vic_dr_cn
			cmp ntc_vic_fpx+1
			bcc ntc_vic_dr_in
			bne ntc_vic_dr_cn
			lda $56
			cmp ntc_vic_fpx
			bcs ntc_vic_dr_cn
ntc_vic_dr_in:
			jsr ntc_vic_col
ntc_vic_dr_cn:
			clc							; the next column's pixels
			lda $5C
			adc $6E
			sta $5C
			bcc ntc_vic_dr_c2
			inc $5D
ntc_vic_dr_c2:
			inc $6D
			lda $6D
			cmp $66
			bne ntc_vic_dr_c
ntc_vic_dr_e:
			rts

; ---- the fast way: the whole image on the screen. The first column's address, then
; a column at a time (+1 in a character, +1593 to the next: 1600 - 7), the pixels'
; loop with its colour, its byte count and its step written into it
ntc_vic_fast:
			lda $68						; the colour
			sta ntc_vic_fl_c1+1
			sta ntc_vic_fl_c2+1
			sta ntc_vic_fy_c1+1
			sta ntc_vic_fy_c2+1
			lda $6E						; bytes a column
			sta ntc_vic_fl_n+1
			sta ntc_vic_fy_n+1
			lda $67						; flip y: Z from the bottom row
			sec
			sbc #1
			asl
			asl
			asl
			sta ntc_vic_fy_z+1
			; the first column drawn: x (flip x: x + w - 1)
			lda $62
			sta $56
			lda $63
			sta $57
			lda $69
			and #1
			beq ntc_vic_f1
			clc
			lda $56
			adc $66
			sta $56
			bcc ntc_vic_f0
			inc $57
ntc_vic_f0:
			lda $56
			bne ntc_vic_f0b
			dec $57
ntc_vic_f0b:
			dec $56
ntc_vic_f1:
			lda $56
			and #7
			sta $5B						; where in its character (0-7)
			lda $57
			lsr
			lda $56
			ror
			lsr
			lsr
			tay
			lda $5B
			clc
			adc ntc_vic_cbl,y
			sta $50
			lda ntc_vic_cbh,y
			adc #0
			sta $51
			lda $64						; + y * 8
			sta $58
			lda #0
			sta $59
			asl $58
			rol $59
			asl $58
			rol $59
			asl $58
			rol $59
			clc
			lda $50
			adc $58
			sta $50
			lda $51
			adc $59
			sta $51
			lda $6C
			sta $52
			lda #0
			sta $53
			lda $66
			sta $6D						; columns left
ntc_vic_f_col:
			lda $69
			and #2
			bne ntc_vic_f_fy
			; down the column
			ldz #0
			ldy #0
ntc_vic_fl_l:
			lda ($5C),y
			tax
			and #$0F
			beq ntc_vic_fl_1
ntc_vic_fl_c1:
			ora #0
			sta [$50],z
ntc_vic_fl_1:
			tza
			clc
			adc #8
			taz
			txa
			lsr
			lsr
			lsr
			lsr
			beq ntc_vic_fl_2
ntc_vic_fl_c2:
			ora #0
			sta [$50],z
ntc_vic_fl_2:
			tza
			clc
			adc #8
			taz
			iny
ntc_vic_fl_n:
			cpy #0
			bne ntc_vic_fl_l
			jmp ntc_vic_f_next
ntc_vic_f_fy:
			; up the column (flip y)
ntc_vic_fy_z:
			ldz #0
			ldy #0
ntc_vic_fy_l:
			lda ($5C),y
			tax
			and #$0F
			beq ntc_vic_fy_1
ntc_vic_fy_c1:
			ora #0
			sta [$50],z
ntc_vic_fy_1:
			tza
			sec
			sbc #8
			taz
			txa
			lsr
			lsr
			lsr
			lsr
			beq ntc_vic_fy_2
ntc_vic_fy_c2:
			ora #0
			sta [$50],z
ntc_vic_fy_2:
			tza
			sec
			sbc #8
			taz
			iny
ntc_vic_fy_n:
			cpy #0
			bne ntc_vic_fy_l
ntc_vic_f_next:
			ldz #0
			dec $6D
			beq ntc_vic_f_done
			clc							; the next column's pixels
			lda $5C
			adc $6E
			sta $5C
			bcc ntc_vic_f_n1
			inc $5D
ntc_vic_f_n1:
			lda $69
			and #1
			bne ntc_vic_f_left
			; to the right
			lda $5B
			cmp #7
			beq ntc_vic_f_rc
			inc $5B
			inw $50
			jmp ntc_vic_f_col
ntc_vic_f_rc:
			lda #0
			sta $5B
			clc
			lda $50
			adc #<1593
			sta $50
			lda $51
			adc #>1593
			sta $51
			jmp ntc_vic_f_col
ntc_vic_f_left:
			lda $5B
			beq ntc_vic_f_lc
			dec $5B
			dew $50
			jmp ntc_vic_f_col
ntc_vic_f_lc:
			lda #7
			sta $5B
			sec
			lda $50
			sbc #<1593
			sta $50
			lda $51
			sbc #>1593
			sta $51
			jmp ntc_vic_f_col
ntc_vic_f_done:
			rts

; one column: the pixels at $5C ($6E bytes), screen x = $56 (0-255) / $57 (high: x 256-319
; for a 320 field), y = $64 / $65, $6F = 1 when it needs clipping
ntc_vic_col:
			; the column's address in the bank: (x >> 3) * 1600 + (x & 7)
			lda $57
			lsr
			lda $56
			ror
			lsr
			lsr
			tay
			lda $56
			and #7
			clc
			adc ntc_vic_cbl,y
			sta $50
			lda ntc_vic_cbh,y
			adc #0
			sta $51
			lda $6C
			sta $52
			lda #0
			sta $53
			lda $6F
			bne ntc_vic_col_clip
			; + y * 8
			lda $64
			sta $58
			lda #0
			sta $59
			asl $58
			rol $59
			asl $58
			rol $59
			asl $58
			rol $59
			clc
			lda $50
			adc $58
			sta $50
			lda $51
			adc $59
			sta $51
			; Z: the row * 8 (flip y: from the bottom)
			lda $69
			and #2
			bne ntc_vic_col_fy
			ldz #0
			lda #8
			sta $5A
			jmp ntc_vic_col_go
ntc_vic_col_fy:
			lda $67
			sec
			sbc #1
			asl
			asl
			asl
			taz
			lda #$F8
			sta $5A
ntc_vic_col_go:
			ldy #0
ntc_vic_col_l:
			lda ($5C),y
			and #$0F
			beq ntc_vic_col_1
			ora $68
			sta [$50],z
ntc_vic_col_1:
			tza
			clc
			adc $5A
			taz
			lda ($5C),y
			lsr
			lsr
			lsr
			lsr
			beq ntc_vic_col_2
			ora $68
			sta [$50],z
ntc_vic_col_2:
			tza
			clc
			adc $5A
			taz
			iny
			cpy $6E
			bne ntc_vic_col_l
			ldz #0
			rts
; clipped: each pixel's row checked, its address worked out ($58 = column base, $5A = row)
ntc_vic_col_clip:
			lda $50
			sta $58
			lda $51
			sta $59
			lda #0
			sta $5B						; the pixel (0 .. h - 1)
ntc_vic_cc_l:
			lda $5B						; the source byte and nybble
			lsr
			tay
			lda ($5C),y
			bcc ntc_vic_cc_lo
			lsr
			lsr
			lsr
			lsr
ntc_vic_cc_lo:
			and #$0F
			beq ntc_vic_cc_n
			ora $68
			sta $5E						; the colour
			; the row: y + p (flip y: y + h - 1 - p), 16 bits
			lda $69
			and #2
			bne ntc_vic_cc_fy
			clc
			lda $64
			adc $5B
			sta $5A
			lda $65
			adc #0
			jmp ntc_vic_cc_r
ntc_vic_cc_fy:
			lda $67
			sec
			sbc #1
			sec
			sbc $5B
			clc
			adc $64
			sta $5A
			lda $65
			adc #0
ntc_vic_cc_r:
			bne ntc_vic_cc_n			; above the top or far below
			lda $5A
			cmp #200
			bcs ntc_vic_cc_n
			sta $50						; row * 8 + the column's base
			lda #0
			sta $51
			asl $50
			rol $51
			asl $50
			rol $51
			asl $50
			rol $51
			clc
			lda $50
			adc $58
			sta $50
			lda $51
			adc $59
			sta $51
			ldz #0
			lda $5E
			sta [$50],z
ntc_vic_cc_n:
			inc $5B
			lda $5B
			cmp $67
			bne ntc_vic_cc_l
			rts

; the text layer: the playfield's characters (every frame, see through) and the panel's
; that changed (opaque)
ntc_vic_text:
			lda #<VIC_TXT
			sta $54
			lda #>VIC_TXT
			sta $55
			lda #<VIC_DIRTY
			sta $60
			lda #>VIC_DIRTY
			sta $61
			lda ntc_vic_back			; the dirty bit for this buffer: 1 A, 2 B
			clc
			adc #1
			sta $62
			lda #0
			sta $57						; row
ntc_vic_tx_r:
			ldy #0
			lda ntc_vic_fw
			beq ntc_vic_tx_pn
ntc_vic_tx_pf:
			lda ($54),y
			cmp #33
			bcs ntc_vic_tx_pfd
ntc_vic_tx_pfn:
			iny
			cpy ntc_vic_fw
			bne ntc_vic_tx_pf
ntc_vic_tx_pn:
			cpy #40
			beq ntc_vic_tx_rd
			lda ($60),y
			and $62
			bne ntc_vic_tx_pnd
ntc_vic_tx_pnn:
			iny
			jmp ntc_vic_tx_pn
ntc_vic_tx_pfd:
			sta $5E						; a character on the playfield: see through
			sty $56
			lda #0
			sta $5F
			jsr ntc_vic_glyph
			ldy $56
			jmp ntc_vic_tx_pfn
ntc_vic_tx_pnd:
			lda ($60),y					; a panel cell to draw: its bit off, opaque
			eor $62
			sta ($60),y
			lda ($54),y
			sta $5E
			sty $56
			lda #1
			sta $5F
			jsr ntc_vic_glyph
			ldy $56
			jmp ntc_vic_tx_pnn
ntc_vic_tx_rd:
			clc
			lda $54
			adc #40
			sta $54
			sta $60
			bcc ntc_vic_tx_r2
			inc $55
			inc $61
ntc_vic_tx_r2:
			inc $57
			lda $57
			cmp #25
			bne ntc_vic_tx_r
			rts

; a character: $5E at column $56, row $57, its colour from VIC_TCOL ($54 + $400 + column),
; $5F = 1 opaque (the paper behind)
ntc_vic_glyph:
			ldy $56
			lda $55						; its colour
			clc
			adc #>(VIC_TCOL-VIC_TXT)
			sta $5B
			lda $54
			sta $5A
			lda ($5A),y
			sta $5D
			; the cell: column * 1600 + row * 64 (64 bytes, 8 a row)
			lda $57
			sta $50
			lda #0
			sta $51
			ldx #6
ntc_vic_gl_m:
			asl $50
			rol $51
			dex
			bne ntc_vic_gl_m
			clc
			lda $50
			adc ntc_vic_cbl,y
			sta $50
			lda $51
			adc ntc_vic_cbh,y
			sta $51
			lda $6C
			sta $52
			lda #0
			sta $53
			; the font: $E000 + character * 8
			lda $5E
			sta $5A
			lda #0
			sta $5B
			asl $5A
			rol $5B
			asl $5A
			rol $5B
			asl $5A
			rol $5B
			clc
			lda $5B
			adc #$E0
			sta $5B
			ldz #0
			ldy #0
ntc_vic_gl_r:
			lda ($5A),y
			sta $59
			ldx #8
ntc_vic_gl_b:
			asl $59
			bcc ntc_vic_gl_0
			lda $5D
			sta [$50],z
			jmp ntc_vic_gl_nx
ntc_vic_gl_0:
			lda $5F
			beq ntc_vic_gl_nx
			lda ntc_vic_paper
			sta [$50],z
ntc_vic_gl_nx:
			inz
			dex
			bne ntc_vic_gl_b
			iny
			cpy #8
			bne ntc_vic_gl_r
			ldz #0
			rts

; ntc_vic_stamp - the image at $60 into both buffers at $62 (x), $64 (y): $68 colour added,
; $69 flips (for the panel: it is not cleared). The whole screen (320 wide)
ntc_vic_stamp:
			lda ntc_vic_fpx
			pha
			lda ntc_vic_fpx+1
			pha
			lda #<320
			sta ntc_vic_fpx
			lda #>320
			sta ntc_vic_fpx+1
			lda #4
			sta $6C
			jsr ntc_vic_draw
			lda #5
			sta $6C
			jsr ntc_vic_draw
			pla
			sta ntc_vic_fpx+1
			pla
			sta ntc_vic_fpx
			rts

; ntc_vic_box - a filled box in both buffers: $62 x, $64 y, $66 w, $67 h (pixels: x, w
; multiples of 8 are fastest), $68 the colour
ntc_vic_box:
			lda #4
			sta $6C
			jsr ntc_vic_box1
			lda #5
			sta $6C
ntc_vic_box1:
			lda #0
			sta $6D						; the pixel column
ntc_vic_bx_c:
			clc
			lda $62
			adc $6D
			sta $56
			lda $63
			adc #0
			sta $57
			; the column's address + y * 8
			lsr
			lda $56
			ror
			lsr
			lsr
			tay
			lda $56
			and #7
			clc
			adc ntc_vic_cbl,y
			sta $50
			lda ntc_vic_cbh,y
			adc #0
			sta $51
			lda $64
			sta $58
			lda #0
			sta $59
			asl $58
			rol $59
			asl $58
			rol $59
			asl $58
			rol $59
			clc
			lda $50
			adc $58
			sta $50
			lda $51
			adc $59
			sta $51
			lda $6C
			sta $52
			lda #0
			sta $53
			ldx $67
			ldz #0
			lda $68
ntc_vic_bx_r:
			sta [$50],z
			tay
			tza
			clc
			adc #8
			taz
			bcc ntc_vic_bx_r1
			inc $51						; (past 32 rows: the next 256 bytes)
ntc_vic_bx_r1:
			tya
			dex
			bne ntc_vic_bx_r
			ldz #0
			inc $6D
			lda $6D
			cmp $66
			bne ntc_vic_bx_c
			rts

;## ntc_sid ntc_plat_data
; ------------------------------------------------------------
; The Sid class's engine: 4 channels (3 tones on SID 1's voices, a noise on SID
; 2's voice 1) as sound effects that move on a frame at a time (ntc_sid_update,
; from Sid.Update): a period (the Mega Drive PSG's: 3579545 / 32 / period Hz)
; that slides and a volume that fades (the voice's sustain level). A channel:
; active, -, period, slide, volume, -, frames, left (12 bytes). Uses $50-$5F.
; ------------------------------------------------------------
ntc_sidch:		ds 4*12
ntc_sid_regs:	db $00, $07, $0E, $20		; each channel's voice: $D400 + this
ntc_sid_init:	db 0						; the SIDs set up (volume, pulse widths)

; the SIDs' volume up and the voices' pulse width a half (once)
ntc_sid_setup:
			lda ntc_sid_init
			bne ntc_sid_su_e
			inc ntc_sid_init
			lda #$0F
			sta $D418
			sta $D438
			ldx #3
ntc_sid_su_l:
			ldy ntc_sid_regs,x
			lda #0
			sta $D402,y
			sta $D405,y					; attack, decay: 0
			lda #8
			sta $D403,y					; pulse width $800: a square
			dex
			bpl ntc_sid_su_l
ntc_sid_su_e:
			rts

; ntc_sid_on - A = the channel, X = its state (12 * channel): started (gated again)
ntc_sid_on:
			sta $5F
			stx $5E
			jsr ntc_sid_setup
			ldx $5F
			ldy ntc_sid_regs,x
			lda #0						; gate off, then on (attack again)
			sta $D404,y
			ldx $5E
			jsr ntc_sid_out
			ldx $5F
			ldy ntc_sid_regs,x
			lda #$41					; pulse, gate
			cpx #3
			bne ntc_sid_on1
			lda #$81					; noise, gate
ntc_sid_on1:
			sta $D404,y
			rts

; ntc_sid_off - A = the channel: silent, not active
ntc_sid_off:
			tax
			ldy ntc_sid_regs,x
			lda #0
			sta $D404,y					; gate off (release 0)
			sta $D406,y					; sustain 0
			txa
			asl
			asl
			sta $5D
			asl
			clc
			adc $5D
			tax
			lda #0
			sta ntc_sidch,x
			rts

; ntc_sid_out - $5F = the channel, X = its state: the frequency and the volume to the SID
ntc_sid_out:
			stx $5E
			ldy $5F
			cpy #3
			beq ntc_sid_o_noise
			; frequency = 1904665 / period
			lda ntc_sidch+2,x
			sta $5A
			lda ntc_sidch+3,x
			sta $5B
			lda #$19
			sta $5C
			lda #$10
			sta $5D
			lda #$1D
			sta $56
			jsr ntc_sid_div				; $5C/$5D/$56 / $5A/$5B
			lda $56						; past 16 bits: the top
			beq ntc_sid_o_f
			lda #$FF
			sta $5C
			sta $5D
ntc_sid_o_f:
			ldx $5F
			ldy ntc_sid_regs,x
			lda $5C
			sta $D400,y
			lda $5D
			sta $D401,y
			jmp ntc_sid_o_vol
ntc_sid_o_noise:
			lda ntc_sidch+2,x			; the kind: 0 high, 1 middle, 2 low, 3 channel 2's
			and #3
			tay
			lda ntc_sid_nhi,y
			bne ntc_sid_o_n1
			lda $D40F					; (channel 2's frequency)
			sta $D421
			lda $D40E
			sta $D420
			jmp ntc_sid_o_vol
ntc_sid_o_n1:
			sta $D421
			lda #0
			sta $D420
ntc_sid_o_vol:
			; the volume now: volume * left / frames (frames 0: the volume)
			ldx $5E
			lda ntc_sidch+6,x
			sta $57						; the volume
			lda ntc_sidch+8,x
			ora ntc_sidch+9,x
			beq ntc_sid_o_v
			lda ntc_sidch+8,x			; divisor: frames
			sta $5A
			lda ntc_sidch+9,x
			sta $5B
			; volume * left (15 * 65535 at most: 24 bits)
			lda ntc_sidch+10,x
			sta $50
			lda ntc_sidch+11,x
			sta $51
			lda #0
			sta $5C
			sta $5D
			sta $56
			ldy $57
			beq ntc_sid_o_v
ntc_sid_o_m:
			clc
			lda $5C
			adc $50
			sta $5C
			lda $5D
			adc $51
			sta $5D
			lda $56
			adc #0
			sta $56
			dey
			bne ntc_sid_o_m
			jsr ntc_sid_div
			lda $5C
			sta $57
ntc_sid_o_v:
			lda $57						; the sustain level
			and #$0F
			asl
			asl
			asl
			asl
			ldx $5F
			ldy ntc_sid_regs,x
			sta $D406,y
			ldx $5E
			rts
ntc_sid_nhi:	db $30, $18, $0C, 0

; $5C/$5D/$56 (24 bits) / $5A/$5B: the quotient in $5C/$5D/$56, the remainder in $58/$59
ntc_sid_div:
			lda #0
			sta $58
			sta $59
			ldx #24
ntc_sid_dv_l:
			asl $5C
			rol $5D
			rol $56
			rol $58
			rol $59
			lda $58
			sec
			sbc $5A
			tay
			lda $59
			sbc $5B
			bcc ntc_sid_dv_n
			sta $59
			sty $58
			inc $5C
ntc_sid_dv_n:
			dex
			bne ntc_sid_dv_l
			rts

; ntc_sid_update - every active channel a frame on
ntc_sid_update:
			lda #0
			sta $5F						; the channel
ntc_sid_u_l:
			lda $5F
			asl
			asl
			sta $5D
			asl
			clc
			adc $5D
			tax
			lda ntc_sidch,x
			beq ntc_sid_u_n
			lda ntc_sidch+8,x			; frames: 0 = held until stopped
			ora ntc_sidch+9,x
			beq ntc_sid_u_sl
			lda ntc_sidch+10,x			; left - 1
			bne ntc_sid_u_d
			dec ntc_sidch+11,x
ntc_sid_u_d:
			dec ntc_sidch+10,x
			lda ntc_sidch+10,x
			ora ntc_sidch+11,x
			beq ntc_sid_u_off
			lda ntc_sidch+11,x			; (gone below 0: off too)
			bpl ntc_sid_u_sl
ntc_sid_u_off:
			lda $5F
			jsr ntc_sid_off
			jmp ntc_sid_u_n
ntc_sid_u_sl:
			clc							; period += slide, kept 1 .. 1023 (a tone)
			lda ntc_sidch+2,x
			adc ntc_sidch+4,x
			sta ntc_sidch+2,x
			lda ntc_sidch+3,x
			adc ntc_sidch+5,x
			sta ntc_sidch+3,x
			lda $5F
			cmp #3
			beq ntc_sid_u_out
			lda ntc_sidch+3,x
			bmi ntc_sid_u_lo
			bne ntc_sid_u_hi
			lda ntc_sidch+2,x
			bne ntc_sid_u_out
ntc_sid_u_lo:
			lda #1
			sta ntc_sidch+2,x
			lda #0
			sta ntc_sidch+3,x
			jmp ntc_sid_u_out
ntc_sid_u_hi:
			cmp #4
			bcc ntc_sid_u_out
			lda #<1023
			sta ntc_sidch+2,x
			lda #>1023
			sta ntc_sidch+3,x
ntc_sid_u_out:
			jsr ntc_sid_out
ntc_sid_u_n:
			inc $5F
			lda $5F
			cmp #4
			bne ntc_sid_u_l
			rts

;## ntc_m65_fontdata
; font8x8_basic (public domain, Daniel Hepper): characters 32-127, 8 bytes each
ntc_m65_fontdata:
			db $00, $00, $00, $00, $00, $00, $00, $00		; 32 space
			db $18, $3C, $3C, $18, $18, $00, $18, $00		; 33 !
